// 취업 가이드 콘텐츠 — 직무 인사이트 · 취업 노하우 · 외국인 비자(교육형).
// CareerGuide 형태를 재사용해 홈 가이드와 동일한 팝업으로 보여준다.
import type { CareerGuide } from "./home-content";
import type { PlatformT } from "../i18n";

// 외국인 구직·취업 관련 비자 — 정확한 상세는 기존 비자 안내(/resources/visa/[code])로 연결.
// code 는 라우팅/매칭 KEY 이므로 번역하지 않는다. label/desc 만 번역.
export function jobVisas(t: PlatformT): { code: string; label: string; desc: string }[] {
  return [
    { code: "D-2", label: t("D-2 유학", "D-2 Study Abroad", "D-2 留学", "D-2 Du học", "D-2 留学", "D-2 Studi"), desc: t("한국 대학에 재학 중인 유학생", "International students enrolled at Korean universities", "在韩国大学就读的留学生", "Du học sinh đang theo học tại đại học Hàn Quốc", "韓国の大学に在学中の留学生", "Mahasiswa asing yang sedang kuliah di universitas Korea") },
    { code: "D-10", label: t("D-10 구직", "D-10 Job Seeking", "D-10 求职", "D-10 Tìm việc", "D-10 求職", "D-10 Pencari Kerja"), desc: t("졸업 후 취업을 준비하는 구직 비자", "Job-seeking visa for preparing employment after graduation", "毕业后准备就业的求职签证", "Visa tìm việc để chuẩn bị đi làm sau khi tốt nghiệp", "卒業後に就職を準備する求職ビザ", "Visa pencari kerja untuk persiapan bekerja setelah lulus") },
    { code: "E-7", label: t("E-7 특정활동", "E-7 Special Activity", "E-7 特定活动", "E-7 Hoạt động đặc định", "E-7 特定活動", "E-7 Aktivitas Khusus"), desc: t("전문 분야 취업 시 받는 대표 취업 비자", "The main work visa for employment in specialized fields", "在专业领域就业时取得的代表性工作签证", "Visa lao động tiêu biểu khi làm việc trong lĩnh vực chuyên môn", "専門分野に就職する際に取得する代表的な就労ビザ", "Visa kerja utama untuk bekerja di bidang khusus") },
    { code: "F-2", label: t("F-2 거주", "F-2 Residence", "F-2 居住", "F-2 Cư trú", "F-2 居住", "F-2 Tinggal"), desc: t("제한 없이 취업할 수 있는 거주 비자", "Residence visa allowing employment without restrictions", "可无限制就业的居住签证", "Visa cư trú cho phép làm việc không giới hạn", "制限なく就職できる居住ビザ", "Visa tinggal yang memungkinkan bekerja tanpa batasan") },
    { code: "F-4", label: t("F-4 재외동포", "F-4 Overseas Korean", "F-4 在外同胞", "F-4 Kiều bào", "F-4 在外同胞", "F-4 Diaspora Korea"), desc: t("폭넓게 취업 가능한 재외동포 비자", "Overseas-Korean visa with broad employment options", "可广泛就业的在外同胞签证", "Visa kiều bào Hàn với nhiều lựa chọn việc làm rộng rãi", "幅広く就職できる在外同胞ビザ", "Visa diaspora Korea dengan pilihan kerja luas") },
    { code: "H-1", label: t("H-1 워킹홀리데이", "H-1 Working Holiday", "H-1 打工度假", "H-1 Working Holiday", "H-1 ワーキングホリデー", "H-1 Working Holiday"), desc: t("협정국 청년의 관광·취업 비자", "Tourism and work visa for youth from partner countries", "协定国青年的旅游·就业签证", "Visa du lịch và làm việc cho thanh niên các nước có hiệp định", "協定国の若者の観光・就労ビザ", "Visa wisata dan kerja untuk pemuda dari negara mitra") }
  ];
}

// 직무 인사이트 — 각 직무가 실제로 무슨 일을 하고, 무엇을 준비하면 좋은지.
export function roleInsights(t: PlatformT): CareerGuide[] {
  return [
    {
      slug: "software-developer",
      emoji: "💻",
      title: t("개발자는\n무슨 일을 하나요?", "What does\na developer do?", "开发者\n做什么工作？", "Lập trình viên\nlàm gì?", "開発者は\n何をしますか？", "Apa yang dilakukan\nseorang developer?"),
      desc: t("코딩만? 실제 하루와 준비물", "Just coding? The real day and what to prepare", "只是写代码？真实的一天与准备事项", "Chỉ code thôi? Một ngày thực tế và cần chuẩn bị gì", "コーディングだけ？実際の一日と準備物", "Cuma ngoding? Keseharian nyata dan yang perlu disiapkan"),
      href: "/talent/jobs",
      ctaLabel: t("개발 직무 공고 보기", "See developer job postings", "查看开发职位招聘", "Xem tin tuyển dụng lập trình", "開発職の求人を見る", "Lihat lowongan developer"),
      body: [
        { heading: t("하는 일", "What they do", "工作内容", "Công việc", "する仕事", "Yang dikerjakan"), text: t("기획과 디자인을 실제로 동작하는 서비스로 만들어요. 화면을 만드는 프론트엔드, 데이터와 서버를 다루는 백엔드, 모바일 앱 개발처럼 분야가 나뉘지만 공통점은 '문제를 코드로 푼다'는 거예요. 새 기능 개발뿐 아니라 버그 수정, 코드 리뷰, 다른 직군과의 협업이 하루의 큰 부분을 차지해요. 처음에는 분야 하나를 골라 깊게 파보는 걸 추천해요. 회사 규모에 따라 한 사람이 여러 분야를 함께 맡기도 해요.", "They turn plans and designs into services that actually run. The field splits into front-end (building screens), back-end (handling data and servers), mobile apps, and more, but they all share one thing: solving problems with code. Beyond building new features, bug fixing, code review, and collaborating with other roles fill much of the day. At first, we recommend picking one area and going deep. Depending on company size, one person may cover several areas.", "把策划和设计变成真正能运行的服务。开发分为做界面的前端、处理数据和服务器的后端、移动应用开发等方向，但共同点都是『用代码解决问题』。除了开发新功能，修bug、代码评审、与其他岗位协作也占了一天的很大部分。刚开始建议先选一个方向深入钻研。根据公司规模，一个人也可能同时负责多个方向。", "Họ biến kế hoạch và thiết kế thành dịch vụ chạy thực sự. Nghề này chia thành front-end (làm giao diện), back-end (xử lý dữ liệu và máy chủ), phát triển ứng dụng di động…, nhưng điểm chung là 'giải quyết vấn đề bằng code'. Ngoài phát triển tính năng mới, sửa lỗi, review code và phối hợp với các bộ phận khác chiếm phần lớn ngày làm việc. Lúc đầu, bạn nên chọn một mảng và đào sâu. Tùy quy mô công ty, một người có thể đảm nhận nhiều mảng cùng lúc.", "企画・デザインを実際に動くサービスにします。画面を作るフロントエンド、データとサーバーを扱うバックエンド、モバイルアプリ開発などに分かれますが、共通点は『問題をコードで解く』ことです。新機能の開発だけでなく、バグ修正、コードレビュー、他職種との協業が一日の大きな部分を占めます。最初は分野を一つ選んで深く掘り下げるのがおすすめです。会社の規模によっては、一人が複数の分野を兼ねることもあります。", "Mereka mengubah rencana dan desain jadi layanan yang benar-benar berjalan. Bidangnya terbagi menjadi front-end (membuat tampilan), back-end (mengelola data dan server), pengembangan aplikasi mobile, dan lainnya, tetapi kesamaannya adalah 'memecahkan masalah dengan kode'. Selain membangun fitur baru, perbaikan bug, tinjauan kode, dan kolaborasi lintas peran mengisi sebagian besar hari. Di awal, sebaiknya pilih satu bidang dan dalami. Tergantung ukuran perusahaan, satu orang bisa menangani beberapa bidang sekaligus.") },
        { heading: t("개발자의 하루", "A developer's day", "开发者的一天", "Một ngày của lập trình viên", "開発者の一日", "Sehari seorang developer"), text: t("많은 팀이 아침에 짧은 회의(스탠드업)로 어제 한 일과 오늘 할 일을 공유해요. 그다음 맡은 기능을 개발하고, 동료가 올린 코드를 리뷰하고, 기획자·디자이너와 세부 사항을 맞추는 일이 이어져요. 예상치 못한 오류가 생기면 원인을 찾아 고치는 데 반나절이 가기도 해요. 팀마다 방식은 다르지만 '혼자 코딩'보다 '함께 만드는 일'에 가깝다는 걸 기억해두세요. 그래서 동료에게 질문하고 진행 상황을 공유하는 소통 능력도 실력만큼 중요하게 여겨져요.", "Many teams start the morning with a short meeting (a stand-up) to share what they did yesterday and plan for today. Then comes building assigned features, reviewing teammates' code, and aligning details with planners and designers. When an unexpected error appears, finding and fixing the cause can take half a day. Every team works differently, but remember: it's closer to 'building together' than 'coding alone.' That's why the ability to ask teammates questions and share progress is valued as much as technical skill.", "很多团队早上会开一个简短的会（站会），分享昨天做了什么、今天要做什么。之后是开发负责的功能、评审同事提交的代码、与策划和设计确认细节。遇到意料之外的错误时，找原因、修复可能就要花上半天。每个团队方式不同，但请记住，这份工作更接近『一起做产品』而不是『一个人写代码』。所以向同事提问、同步进度的沟通能力，和技术实力一样受重视。", "Nhiều nhóm bắt đầu buổi sáng bằng cuộc họp ngắn (stand-up) để chia sẻ hôm qua đã làm gì và hôm nay làm gì. Sau đó là phát triển tính năng được giao, review code đồng nghiệp gửi lên và thống nhất chi tiết với planner, designer. Khi gặp lỗi bất ngờ, việc tìm nguyên nhân và sửa có thể mất nửa ngày. Mỗi nhóm làm một kiểu, nhưng hãy nhớ: công việc này gần với 'cùng nhau xây dựng' hơn là 'code một mình'. Vì vậy, khả năng hỏi đồng nghiệp và chia sẻ tiến độ cũng được coi trọng ngang với năng lực kỹ thuật.", "多くのチームは朝に短いミーティング(スタンドアップ)で、昨日やったことと今日やることを共有します。その後、担当機能の開発、同僚のコードのレビュー、企画者・デザイナーとの細部のすり合わせが続きます。予期せぬエラーが出ると、原因を探して直すのに半日かかることもあります。チームごとにやり方は違いますが、『一人でコーディング』より『みんなで作る仕事』に近いことを覚えておきましょう。だから同僚に質問したり進捗を共有したりするコミュニケーション力も、技術力と同じくらい重視されます。", "Banyak tim memulai pagi dengan rapat singkat (stand-up) untuk berbagi apa yang dikerjakan kemarin dan rencana hari ini. Setelah itu mengembangkan fitur yang ditugaskan, meninjau kode rekan, dan menyelaraskan detail dengan planner dan desainer. Saat muncul error tak terduga, mencari dan memperbaiki penyebabnya bisa makan setengah hari. Cara kerja tiap tim berbeda, tapi ingat: pekerjaan ini lebih dekat ke 'membangun bersama' daripada 'ngoding sendirian'. Karena itu, kemampuan bertanya pada rekan dan berbagi perkembangan dihargai sama seperti kemampuan teknis.") },
        { heading: t("준비하면 좋은 것", "Good to prepare", "值得准备的", "Nên chuẩn bị", "準備すると良いもの", "Baik untuk disiapkan"), text: t("작은 거라도 '직접 만든 결과물' 1~2개가 이력서를 살려요. 토이 프로젝트·클론 코딩·팀 과제 무엇이든 GitHub에 올리고, README에 무엇을 왜 만들었는지, 어떤 기술을 썼는지, 어려웠던 점을 어떻게 해결했는지 적어두세요. 실제로 접속해볼 수 있는 링크가 있으면 더 좋아요. 완성도 높은 1개가 미완성 5개보다 훨씬 설득력 있어요. 커밋 기록이 꾸준히 쌓여 있으면 성실함을 보여주는 데도 도움이 돼요.", "Even small, 1–2 'things you built yourself' bring a resume to life. Put any toy project, clone coding, or team assignment on GitHub, and write in the README what you built and why, which technologies you used, and how you solved the hard parts. A live link people can actually open is even better. One polished project is far more convincing than five unfinished ones. A steady commit history also helps show that you're consistent.", "哪怕很小，1~2个『亲手做的成果』就能让简历鲜活。玩具项目、克隆编程、团队作业，什么都可以上传到GitHub，并在README里写清做了什么、为什么做、用了哪些技术、难点是怎么解决的。如果有能实际访问的链接就更好了。一个完成度高的项目，比五个半成品更有说服力。持续积累的提交记录，也有助于体现你的踏实。", "Dù nhỏ, 1–2 'sản phẩm bạn tự làm' cũng làm CV sống động. Hãy đưa dự án nhỏ, clone coding hay bài tập nhóm lên GitHub, và ghi trong README bạn làm gì, vì sao, dùng công nghệ nào, đã giải quyết phần khó ra sao. Có đường link truy cập được thật thì càng tốt. Một dự án hoàn thiện thuyết phục hơn nhiều so với năm dự án dang dở. Lịch sử commit đều đặn cũng giúp thể hiện sự chăm chỉ của bạn.", "小さくても『自分で作った成果物』1〜2個が履歴書を生かします。トイプロジェクト・クローンコーディング・チーム課題、何でもGitHubに上げ、READMEに何をなぜ作ったか、どんな技術を使ったか、難しかった点をどう解決したかを書いておきましょう。実際にアクセスできるリンクがあればさらに良いです。完成度の高い1つは、未完成の5つよりずっと説得力があります。コミット履歴がコツコツ積み重なっていると、誠実さを示すのにも役立ちます。", "Meski kecil, 1–2 'karya buatan sendiri' menghidupkan resume. Unggah proyek kecil, clone coding, atau tugas tim apa pun ke GitHub, lalu tulis di README apa yang dibuat dan mengapa, teknologi yang dipakai, serta cara mengatasi bagian sulit. Tautan yang benar-benar bisa dibuka akan lebih baik lagi. Satu proyek yang rapi jauh lebih meyakinkan daripada lima yang setengah jadi. Riwayat commit yang konsisten juga membantu menunjukkan ketekunan Anda.") },
        { heading: t("면접에서 보는 것", "What interviewers look for", "面试看什么", "Nhà tuyển dụng xem gì", "面接で見られること", "Yang dilihat pewawancara"), text: t("신입 개발자 면접에서는 모든 걸 아는지보다 '어떻게 생각하는지'를 많이 봐요. 코딩 테스트나 기술 질문이 나오면 바로 정답을 말하기보다 생각의 흐름을 소리 내어 설명해보세요. 프로젝트에 대해서는 '왜 이 기술을 골랐나요?', '가장 어려웠던 버그는?' 같은 질문이 자주 나와요. 내 코드를 내 말로 설명할 수 있게 미리 연습해두세요. 모르는 부분은 솔직히 말하고 어떻게 찾아볼지 덧붙이면 오히려 좋은 인상을 줄 수 있어요.", "In junior developer interviews, how you think matters more than knowing everything. When a coding test or technical question comes up, explain your thought process out loud instead of jumping straight to an answer. About your projects, expect questions like 'Why did you choose this technology?' or 'What was the hardest bug?' Practice explaining your own code in your own words beforehand. Being honest about what you don't know and adding how you'd look it up can actually leave a good impression.", "新人开发者面试中，比起是否什么都懂，更看重『你怎么思考』。遇到编程测试或技术问题时，与其直接说答案，不如把思路说出来。关于项目，常会被问『为什么选这个技术？』『最难的bug是什么？』。提前练习用自己的话讲清楚自己的代码。不懂的地方坦诚说出来，再补充你会怎么去查，反而能留下好印象。", "Trong phỏng vấn lập trình viên mới, cách bạn suy nghĩ được chú ý hơn việc biết hết mọi thứ. Khi gặp bài test code hay câu hỏi kỹ thuật, hãy nói to luồng suy nghĩ thay vì vội đưa đáp án. Về dự án, thường có câu như 'Vì sao chọn công nghệ này?', 'Lỗi khó nhất là gì?'. Hãy luyện trước cách giải thích code của mình bằng lời của chính mình. Thành thật nói phần mình chưa biết và nói thêm cách sẽ tìm hiểu có thể còn tạo ấn tượng tốt.", "新人開発者の面接では、すべてを知っているかより『どう考えるか』をよく見ます。コーディングテストや技術質問が出たら、すぐ正解を言うより思考の流れを声に出して説明しましょう。プロジェクトについては『なぜこの技術を選んだのか』『一番難しかったバグは?』といった質問がよく出ます。自分のコードを自分の言葉で説明できるよう練習しておきましょう。分からない部分は正直に言い、どう調べるかを付け加えると、むしろ良い印象を与えられます。", "Dalam wawancara developer pemula, cara Anda berpikir lebih diperhatikan daripada tahu segalanya. Saat ada tes coding atau pertanyaan teknis, jelaskan alur pikir Anda dengan suara keras alih-alih langsung menjawab. Tentang proyek, sering muncul pertanyaan seperti 'Mengapa memilih teknologi ini?' atau 'Bug tersulit apa?'. Latih menjelaskan kode Anda dengan kata-kata sendiri sebelumnya. Jujur soal yang belum Anda ketahui lalu menambahkan cara mencarinya justru bisa meninggalkan kesan baik.") },
        { heading: t("유학생이라면", "For international students", "如果你是留学生", "Nếu bạn là du học sinh", "留学生なら", "Untuk mahasiswa asing"), text: t("한국 개발팀은 문서와 회의를 한국어로 진행하는 경우가 많지만, 코드와 기술 용어는 영어가 기본이라 유학생에게도 문이 열려 있는 분야예요. 다국어 능력은 해외 서비스나 글로벌 사용자를 다루는 팀에서 강점이 될 수 있어요. 공고에서 요구하는 한국어 수준을 꼭 확인하고, 업무 대화에 자주 쓰는 표현(배포, 이슈, 리뷰 등)을 미리 익혀두면 적응이 훨씬 수월해요. 기술 블로그나 README를 한국어로 써보는 것도 좋은 연습이 돼요.", "Korean dev teams often run documents and meetings in Korean, but code and technical terms are English by default, so the field is open to international students too. Speaking several languages can be a strength on teams that handle overseas services or global users. Always check the Korean level a posting asks for, and learning common work expressions in advance (deploy, issue, review, etc.) makes adjusting much easier. Writing a tech blog post or README in Korean is also good practice.", "韩国的开发团队很多用韩语写文档、开会，但代码和技术术语基本是英语，所以这是对留学生也敞开大门的领域。多语言能力在负责海外服务或全球用户的团队里可能成为优势。一定要确认招聘要求的韩语水平，提前熟悉工作中常用的表达（部署、问题单、评审等），适应起来会轻松很多。试着用韩语写技术博客或README，也是很好的练习。", "Các nhóm phát triển ở Hàn thường dùng tiếng Hàn cho tài liệu và họp, nhưng code và thuật ngữ kỹ thuật mặc định là tiếng Anh, nên đây là lĩnh vực mở cửa cho cả du học sinh. Khả năng đa ngôn ngữ có thể là thế mạnh ở các nhóm làm dịch vụ nước ngoài hoặc người dùng toàn cầu. Hãy kiểm tra trình độ tiếng Hàn tin tuyển dụng yêu cầu, và học trước các cách nói hay dùng trong công việc (triển khai, issue, review…) để thích nghi dễ hơn nhiều. Thử viết blog kỹ thuật hoặc README bằng tiếng Hàn cũng là cách luyện tập tốt.", "韓国の開発チームは文書や会議を韓国語で行うことが多いですが、コードや技術用語は英語が基本なので、留学生にも門が開かれている分野です。多言語能力は、海外向けサービスやグローバルユーザーを扱うチームで強みになり得ます。求人が求める韓国語レベルを必ず確認し、業務会話でよく使う表現(デプロイ、イシュー、レビューなど)を先に覚えておくと、適応がずっと楽になります。技術ブログやREADMEを韓国語で書いてみるのも良い練習になります。", "Tim developer di Korea sering memakai bahasa Korea untuk dokumen dan rapat, tetapi kode dan istilah teknis pada dasarnya berbahasa Inggris, jadi bidang ini terbuka juga bagi mahasiswa asing. Kemampuan multibahasa bisa menjadi kekuatan di tim yang menangani layanan luar negeri atau pengguna global. Pastikan cek tingkat bahasa Korea yang diminta lowongan, dan pelajari dulu ungkapan kerja yang sering dipakai (deploy, isu, review, dll.) agar adaptasi jauh lebih mudah. Menulis blog teknis atau README dalam bahasa Korea juga latihan yang bagus.") },
        { heading: t("이런 사람에게", "A good fit for", "适合这样的人", "Phù hợp với", "こんな人に", "Cocok untuk"), text: t("문제를 쪼개 해결하는 걸 좋아하고, 새로운 걸 계속 배우는 게 즐거운 사람에게 잘 맞아요. 기술은 빠르게 바뀌기 때문에 모르는 걸 찾아보고 직접 시도해보는 습관이 전공보다 중요할 때가 많아요. 시작해보고 싶다면 관심 있는 분야 하나를 고르고, 작은 프로젝트 하나를 끝까지 완성해보세요. 그 경험이 첫 이력서의 가장 좋은 재료가 돼요. 처음부터 잘하는 사람은 없으니 조급해하지 않아도 괜찮아요.", "Great for people who enjoy breaking problems down to solve them and love continuously learning new things. Technology changes fast, so the habit of looking things up and trying them yourself often matters more than your major. If you want to start, pick one area you're curious about and finish one small project all the way. That experience becomes the best material for your first resume. No one is good at it from the start, so there's no need to rush.", "适合喜欢拆解问题去解决、乐于不断学习新事物的人。技术变化很快，所以主动查资料、亲手尝试的习惯，很多时候比专业更重要。如果想开始，就选一个感兴趣的方向，把一个小项目从头做到尾。这段经历会成为你第一份简历最好的素材。没有人一开始就很厉害，所以不用着急。", "Rất hợp với người thích chia nhỏ vấn đề để giải quyết và thích liên tục học điều mới. Công nghệ thay đổi nhanh nên thói quen tự tìm hiểu và tự thử nhiều khi quan trọng hơn chuyên ngành. Nếu muốn bắt đầu, hãy chọn một mảng bạn quan tâm và hoàn thành trọn vẹn một dự án nhỏ. Trải nghiệm đó sẽ là chất liệu tốt nhất cho CV đầu tiên. Không ai giỏi ngay từ đầu, nên bạn không cần vội.", "問題を分解して解決するのが好きで、新しいことを学び続けるのが楽しい人によく合います。技術は速く変わるので、分からないことを調べて自分で試す習慣が専攻より大切なことも多いです。始めてみたいなら、興味のある分野を一つ選び、小さなプロジェクトを一つ最後まで完成させてみましょう。その経験が最初の履歴書の一番の材料になります。最初からできる人はいないので、焦らなくて大丈夫です。", "Cocok bagi yang suka memecah masalah untuk menyelesaikannya dan senang terus belajar hal baru. Teknologi berubah cepat, jadi kebiasaan mencari tahu dan mencoba sendiri sering lebih penting daripada jurusan. Jika ingin mulai, pilih satu bidang yang Anda minati dan selesaikan satu proyek kecil sampai tuntas. Pengalaman itu jadi materi terbaik untuk resume pertama Anda. Tidak ada yang langsung mahir sejak awal, jadi tak perlu terburu-buru.") }
      ]
    },
    {
      slug: "marketer",
      emoji: "📣",
      title: t("마케터는\n무슨 일을 하나요?", "What does\na marketer do?", "营销人员\n做什么工作？", "Marketer\nlàm gì?", "マーケターは\n何をしますか？", "Apa yang dilakukan\nseorang marketer?"),
      desc: t("감이 아니라 숫자로 일해요", "Working by numbers, not by gut", "靠数字而非直觉工作", "Làm việc bằng con số, không phải cảm tính", "勘ではなく数字で働きます", "Bekerja dengan angka, bukan firasat"),
      href: "/talent/jobs",
      ctaLabel: t("마케팅 직무 공고 보기", "See marketing job postings", "查看营销职位招聘", "Xem tin tuyển dụng marketing", "マーケ職の求人を見る", "Lihat lowongan marketing"),
      body: [
        { heading: t("하는 일", "What they do", "工作内容", "Công việc", "する仕事", "Yang dikerjakan"), text: t("고객을 모으고 움직이게 만들어요. 콘텐츠·광고·SNS를 운영하고, 결과를 숫자(전환율·클릭·매출)로 확인하며 다음 액션을 정해요. 브랜드 마케팅, 퍼포먼스 마케팅, 콘텐츠 마케팅, CRM처럼 세부 분야가 다양해서 공고마다 실제 업무가 꽤 달라요. 지원 전에 '이 자리는 무엇을 늘리는 역할인지'부터 확인해보세요. 같은 마케터라도 매일 광고 숫자를 보는 자리와 브랜드 이야기를 만드는 자리는 필요한 역량이 달라요.", "They attract customers and get them to act. They run content, ads, and social media, check results in numbers (conversion, clicks, revenue), and decide the next action. There are many specialties—brand, performance, content marketing, CRM—so actual duties vary quite a bit from posting to posting. Before applying, first check 'what this role is meant to grow.' Even under the same 'marketer' title, a role watching ad numbers daily and one crafting brand stories need different skills.", "吸引并促动客户。运营内容、广告、社交媒体，用数字（转化率、点击、销售额）确认结果并决定下一步行动。品牌营销、效果营销、内容营销、CRM等细分方向很多，所以每个招聘的实际工作差别不小。投递前先确认『这个岗位是负责提升什么的』。同样是营销人员，每天盯广告数据的岗位和打造品牌故事的岗位，需要的能力并不相同。", "Họ thu hút và thúc đẩy khách hàng hành động. Vận hành nội dung, quảng cáo, mạng xã hội, kiểm tra kết quả bằng con số (tỷ lệ chuyển đổi, lượt nhấp, doanh thu) và quyết định bước tiếp theo. Có nhiều mảng như brand marketing, performance marketing, content marketing, CRM nên công việc thực tế mỗi tin tuyển dụng khá khác nhau. Trước khi ứng tuyển, hãy xem 'vị trí này có nhiệm vụ tăng điều gì'. Cùng là marketer, nhưng vị trí theo dõi số liệu quảng cáo hằng ngày và vị trí xây dựng câu chuyện thương hiệu cần năng lực khác nhau.", "顧客を集め、動かします。コンテンツ・広告・SNSを運営し、結果を数字(コンバージョン率・クリック・売上)で確認して次のアクションを決めます。ブランドマーケティング、パフォーマンスマーケティング、コンテンツマーケティング、CRMなど細かい分野が多様で、求人ごとに実際の業務はかなり違います。応募前に『このポジションは何を伸ばす役割か』をまず確認しましょう。同じマーケターでも、毎日広告の数字を見るポジションとブランドの物語を作るポジションでは、必要な力が違います。", "Mereka menarik dan menggerakkan pelanggan. Menjalankan konten, iklan, media sosial, memeriksa hasil dalam angka (konversi, klik, pendapatan), dan menentukan aksi berikutnya. Spesialisasinya beragam—brand, performance, content marketing, CRM—sehingga tugas nyata tiap lowongan cukup berbeda. Sebelum melamar, cek dulu 'peran ini bertugas meningkatkan apa'. Meski sama-sama marketer, posisi yang memantau angka iklan setiap hari dan posisi yang membangun cerita merek membutuhkan kemampuan berbeda.") },
        { heading: t("마케터의 일주일", "A marketer's week", "营销人员的一周", "Một tuần của marketer", "マーケターの一週間", "Seminggu seorang marketer"), text: t("한 주는 보통 지난 성과를 돌아보는 데서 시작해요. 광고나 콘텐츠 지표를 확인하고, 잘된 것과 안 된 것을 정리해 이번 주 계획을 세워요. 주중에는 콘텐츠를 만들거나 광고 문구·이미지를 바꿔 테스트하고, 디자이너·영업·기획 팀과 일정을 맞춰요. 주 후반에는 결과를 다시 보고 다음 실험을 준비하는 흐름이 반복돼요. 작은 실험을 빠르게 반복하는 게 마케터 일의 기본 리듬이에요.", "A week usually starts by reviewing past results. You check ad and content metrics, sort out what worked and what didn't, and plan the week. Midweek you create content or test new ad copy and images, and coordinate schedules with design, sales, and planning teams. Toward the end of the week you look at the results again and prepare the next experiment—and the cycle repeats. Running small experiments quickly and repeatedly is the basic rhythm of marketing work.", "一周通常从回顾上周成果开始。查看广告和内容数据，整理哪些有效、哪些无效，制定本周计划。周中制作内容，或更换广告文案、图片做测试，并与设计、销售、策划团队对齐日程。到了周后半，再看一遍结果、准备下一个实验，如此循环。快速重复小实验，是营销工作的基本节奏。", "Một tuần thường bắt đầu bằng việc xem lại kết quả trước đó. Bạn kiểm tra chỉ số quảng cáo và nội dung, tổng hợp cái hiệu quả và chưa hiệu quả rồi lên kế hoạch tuần. Giữa tuần, bạn làm nội dung hoặc đổi câu chữ, hình ảnh quảng cáo để thử nghiệm, và thống nhất lịch với các nhóm thiết kế, kinh doanh, planning. Cuối tuần lại xem kết quả và chuẩn bị thử nghiệm tiếp theo—chu kỳ cứ thế lặp lại. Lặp lại nhanh những thử nghiệm nhỏ là nhịp điệu cơ bản của nghề marketing.", "一週間はたいてい前回の成果を振り返ることから始まります。広告やコンテンツの指標を確認し、うまくいったこととそうでないことを整理して今週の計画を立てます。週の半ばはコンテンツを作ったり、広告のコピー・画像を変えてテストしたりし、デザイン・営業・企画チームと日程を合わせます。週の後半には結果を再び見て次の実験を準備する流れが繰り返されます。小さな実験を素早く繰り返すのが、マーケターの仕事の基本リズムです。", "Seminggu biasanya dimulai dengan meninjau hasil sebelumnya. Anda memeriksa metrik iklan dan konten, merangkum yang berhasil dan tidak, lalu menyusun rencana minggu ini. Di tengah minggu Anda membuat konten atau menguji copy dan gambar iklan baru, serta menyelaraskan jadwal dengan tim desain, sales, dan planning. Menjelang akhir minggu Anda melihat hasil lagi dan menyiapkan eksperimen berikutnya—siklus ini terus berulang. Menjalankan eksperimen kecil dengan cepat dan berulang adalah ritme dasar pekerjaan marketer.") },
        { heading: t("준비하면 좋은 것", "Good to prepare", "值得准备的", "Nên chuẩn bị", "準備すると良いもの", "Baik untuk disiapkan"), text: t("직접 운영해본 SNS 계정, 블로그, 소규모 캠페인이 큰 어필이 돼요. '팔로워 0→500', '방문자 2배'처럼 숫자로 정리하고, 무엇을 바꿨더니 그렇게 됐는지까지 적어보세요. 스프레드시트로 간단한 데이터를 정리하는 능력이나 기본적인 분석 도구를 써본 경험도 도움이 돼요. 거창하지 않아도 '스스로 실험해봤다'는 점이 중요해요. 포트폴리오에는 결과 화면 캡처와 함께 내가 세운 가설을 짧게 적어두면 좋아요.", "A social account, blog, or small campaign you ran yourself is a big plus. Sum it up in numbers like 'followers 0→500' or 'visitors doubled,' and add what you changed to get there. Being able to organize simple data in a spreadsheet or having used basic analytics tools also helps. It doesn't have to be grand—what matters is that you experimented on your own. In your portfolio, add a short note on the hypothesis you set alongside screenshots of the results.", "自己运营过的社交账号、博客、小型活动会是很大加分。用『粉丝0→500』『访客翻倍』这样的数字来整理，并写上改了什么才有这个结果。会用表格整理简单数据、用过基础分析工具也很有帮助。不必宏大，重要的是『自己动手试过』。作品集里除了结果截图，最好再简短写下你当时提出的假设。", "Tài khoản mạng xã hội, blog hay chiến dịch nhỏ bạn tự vận hành là điểm cộng lớn. Hãy tóm bằng con số như 'follower 0→500', 'khách gấp đôi', và ghi cả việc bạn đã thay đổi gì để đạt được. Khả năng sắp xếp dữ liệu đơn giản bằng bảng tính hay từng dùng công cụ phân tích cơ bản cũng hữu ích. Không cần to tát—quan trọng là bạn đã 'tự thử nghiệm'. Trong portfolio, hãy ghi ngắn giả thuyết bạn đặt ra kèm ảnh chụp kết quả.", "自分で運営したSNSアカウント、ブログ、小規模キャンペーンが大きなアピールになります。『フォロワー0→500』『訪問者2倍』のように数字で整理し、何を変えたらそうなったかまで書いてみましょう。スプレッドシートで簡単なデータを整理する力や、基本的な分析ツールを使った経験も役立ちます。大げさでなくても『自分で実験してみた』ことが大切です。ポートフォリオには結果画面のキャプチャと一緒に、自分が立てた仮説を短く書いておくと良いです。", "Akun media sosial, blog, atau kampanye kecil yang Anda jalankan sendiri jadi nilai plus besar. Rangkum dalam angka seperti 'follower 0→500' atau 'pengunjung 2 kali lipat', dan tulis juga apa yang Anda ubah hingga hasilnya begitu. Kemampuan merapikan data sederhana di spreadsheet atau pengalaman memakai alat analitik dasar juga membantu. Tak perlu besar—yang penting Anda pernah bereksperimen sendiri. Di portofolio, tambahkan catatan singkat tentang hipotesis Anda bersama tangkapan layar hasilnya.") },
        { heading: t("면접에서 보는 것", "What interviewers look for", "面试看什么", "Nhà tuyển dụng xem gì", "面接で見られること", "Yang dilihat pewawancara"), text: t("마케팅 면접에서는 '좋아하는 광고가 뭐예요?'처럼 감각을 묻는 질문과 '이 지표가 떨어지면 어떻게 할 건가요?'처럼 논리를 묻는 질문이 함께 나와요. 지원 회사의 SNS·광고·앱을 미리 써보고 개선 아이디어를 하나쯤 준비해가면 좋아요. 아이디어를 말할 때는 '누구에게, 무엇을, 어떻게 측정할지'까지 이어서 설명하면 설득력이 높아져요. 숫자로 말하는 습관을 면접에서도 보여주면 좋은 신호가 돼요.", "Marketing interviews mix questions about your instincts, like 'What's an ad you love?', with questions about logic, like 'What would you do if this metric dropped?' Try the company's social channels, ads, or app beforehand and bring one improvement idea. When you share an idea, explain 'for whom, what, and how you'd measure it'—that makes it far more convincing. Showing the habit of speaking in numbers during the interview is a good sign too.", "营销面试里既有『你喜欢哪个广告？』这类考察感觉的问题，也有『这个指标下降了你会怎么做？』这类考察逻辑的问题。提前用一用应聘公司的社交账号、广告、应用，准备一个改进点子会很好。讲点子时，连同『面向谁、做什么、怎么衡量』一起说明，会更有说服力。在面试中也展现出用数字说话的习惯，会是很好的信号。", "Phỏng vấn marketing có cả câu hỏi về cảm quan như 'Quảng cáo bạn thích là gì?' lẫn câu hỏi về logic như 'Nếu chỉ số này giảm bạn sẽ làm gì?'. Hãy dùng thử trước mạng xã hội, quảng cáo, ứng dụng của công ty và chuẩn bị một ý tưởng cải thiện. Khi trình bày ý tưởng, nói luôn 'cho ai, làm gì, đo lường thế nào' sẽ thuyết phục hơn nhiều. Thể hiện thói quen nói bằng con số ngay trong buổi phỏng vấn cũng là tín hiệu tốt.", "マーケティングの面接では『好きな広告は?』のように感覚を問う質問と、『この指標が下がったらどうしますか?』のように論理を問う質問が一緒に出ます。応募企業のSNS・広告・アプリを事前に使ってみて、改善アイデアを一つ用意していくと良いです。アイデアを話すときは『誰に、何を、どう測るか』までつなげて説明すると説得力が高まります。数字で話す習慣を面接でも見せられると、良いサインになります。", "Wawancara marketing menggabungkan pertanyaan soal insting, seperti 'Iklan apa yang Anda suka?', dengan pertanyaan logika, seperti 'Apa yang akan Anda lakukan jika metrik ini turun?'. Coba dulu media sosial, iklan, atau aplikasi perusahaan dan siapkan satu ide perbaikan. Saat menyampaikan ide, jelaskan sekalian 'untuk siapa, apa, dan bagaimana mengukurnya' agar jauh lebih meyakinkan. Menunjukkan kebiasaan berbicara dengan angka saat wawancara juga menjadi sinyal yang baik.") },
        { heading: t("유학생이라면", "For international students", "如果你是留学生", "Nếu bạn là du học sinh", "留学生なら", "Untuk mahasiswa asing"), text: t("모국어와 모국 문화에 대한 이해는 해외 진출이나 외국인 고객을 겨냥하는 회사에서 실제 강점이 될 수 있어요. 예를 들어 모국 SNS 트렌드를 정리하거나, 한국 브랜드 콘텐츠를 모국어로 현지화해본 경험은 좋은 포트폴리오가 돼요. 다만 국내 고객 대상 마케팅은 한국어 문장 감각이 중요하니, 지원 직무가 어느 시장을 대상으로 하는지 먼저 확인하세요. 한국어와 모국어로 같은 콘텐츠를 만들어 반응을 비교해본 경험도 좋은 이야깃거리가 돼요.", "Your native language and understanding of your home culture can be a real strength at companies expanding overseas or targeting foreign customers. For example, summarizing social media trends in your home country or localizing a Korean brand's content into your language makes a good portfolio piece. That said, marketing to Korean customers relies on a feel for Korean copy, so first check which market the role targets. Making the same content in Korean and your native language and comparing the responses also makes a great story.", "母语和对本国文化的理解，在拓展海外或面向外国客户的公司里可以成为真正的优势。比如整理本国社交媒体趋势，或把韩国品牌的内容本地化成母语，都能成为很好的作品集。不过面向韩国本土客户的营销很看重韩语文案感觉，所以先确认应聘岗位面向哪个市场。用韩语和母语制作同一内容并比较反响的经历，也是很好的谈资。", "Tiếng mẹ đẻ và hiểu biết về văn hóa quê nhà có thể là thế mạnh thực sự ở những công ty mở rộng ra nước ngoài hoặc nhắm tới khách hàng nước ngoài. Ví dụ, tổng hợp xu hướng mạng xã hội ở nước bạn hay bản địa hóa nội dung của một thương hiệu Hàn sang tiếng mẹ đẻ đều là portfolio tốt. Tuy nhiên, marketing cho khách hàng Hàn cần cảm nhận câu chữ tiếng Hàn, nên hãy xem trước vị trí đó nhắm tới thị trường nào. Kinh nghiệm làm cùng một nội dung bằng tiếng Hàn và tiếng mẹ đẻ rồi so sánh phản hồi cũng là câu chuyện hay.", "母国語と母国文化への理解は、海外進出や外国人顧客を狙う会社で実際の強みになり得ます。例えば、母国のSNSトレンドをまとめたり、韓国ブランドのコンテンツを母国語にローカライズしたりした経験は良いポートフォリオになります。ただし国内顧客向けのマーケティングは韓国語の文章感覚が大切なので、応募職種がどの市場を対象にしているかを先に確認しましょう。韓国語と母国語で同じコンテンツを作り、反応を比べた経験も良い話のネタになります。", "Bahasa ibu dan pemahaman budaya negara asal bisa menjadi kekuatan nyata di perusahaan yang ekspansi ke luar negeri atau menyasar pelanggan asing. Misalnya, merangkum tren media sosial di negara Anda atau melokalkan konten merek Korea ke bahasa Anda bisa jadi portofolio yang bagus. Namun, marketing untuk pelanggan Korea mengandalkan rasa bahasa Korea, jadi cek dulu pasar mana yang disasar posisi tersebut. Pengalaman membuat konten yang sama dalam bahasa Korea dan bahasa ibu lalu membandingkan responsnya juga jadi bahan cerita yang bagus.") },
        { heading: t("이런 사람에게", "A good fit for", "适合这样的人", "Phù hợp với", "こんな人に", "Cocok untuk"), text: t("사람의 마음을 관찰하는 걸 좋아하고, 결과를 숫자로 확인하며 개선하는 걸 즐기는 사람에게 잘 맞아요. 아이디어가 많은 것도 좋지만, 실패한 실험에서 이유를 찾아 다음에 반영하는 끈기가 더 중요해요. 오늘 본 광고 하나를 골라 '누구를 노렸고, 왜 이렇게 만들었을까'를 생각해보는 것부터 연습해보세요. 이런 연습이 쌓이면 면접에서 말할 거리도 자연스럽게 늘어나요.", "Great for people who like observing what moves others and enjoy checking results in numbers to improve. Having lots of ideas is nice, but the persistence to find out why an experiment failed and apply it next time matters more. Start practicing by picking one ad you saw today and asking, 'Who was it aimed at, and why was it made this way?' As this practice builds up, you'll naturally have more to talk about in interviews.", "适合喜欢观察人心、乐于用数字确认结果并改进的人。点子多固然好，但从失败的实验里找原因、下次改进的韧性更重要。可以从挑一则今天看到的广告，想想『它瞄准的是谁、为什么这样做』开始练习。这样的练习积累多了，面试时能聊的内容也会自然变多。", "Rất hợp với người thích quan sát tâm lý người khác và thích kiểm tra kết quả bằng con số để cải thiện. Nhiều ý tưởng là tốt, nhưng sự bền bỉ tìm ra lý do thử nghiệm thất bại và áp dụng cho lần sau còn quan trọng hơn. Hãy bắt đầu luyện tập bằng cách chọn một quảng cáo bạn thấy hôm nay và nghĩ 'nó nhắm tới ai, vì sao làm như vậy'. Khi luyện tập như vậy nhiều lên, bạn sẽ tự nhiên có thêm điều để nói khi phỏng vấn.", "人の心を観察するのが好きで、結果を数字で確認しながら改善するのを楽しむ人によく合います。アイデアが多いのも良いですが、失敗した実験から理由を見つけて次に活かす粘り強さの方が大切です。今日見た広告を一つ選び、『誰を狙い、なぜこう作ったのか』を考えることから練習してみましょう。こうした練習が積み重なると、面接で話せることも自然に増えていきます。", "Cocok bagi yang suka mengamati apa yang menggerakkan orang dan senang memeriksa hasil dalam angka untuk memperbaikinya. Punya banyak ide itu bagus, tapi ketekunan mencari tahu mengapa eksperimen gagal lalu menerapkannya berikutnya jauh lebih penting. Mulailah berlatih dengan memilih satu iklan yang Anda lihat hari ini dan bertanya, 'Siapa sasarannya, dan mengapa dibuat seperti ini?' Seiring latihan ini bertambah, bahan pembicaraan Anda saat wawancara juga ikut bertambah secara alami.") }
      ]
    },
    {
      slug: "designer-portfolio",
      emoji: "🎨",
      title: t("디자이너\n포트폴리오, 뭘 넣죠?", "Designer portfolio:\nwhat goes in?", "设计师作品集\n放什么？", "Portfolio thiết kế:\ncho gì vào?", "デザイナーの\nポートフォリオ、何を入れる？", "Portofolio desainer:\napa isinya?"),
      desc: t("결과물보다 '과정'을 보여주세요", "Show the 'process,' not just the final work", "比起成果，更要展示『过程』", "Hãy cho thấy 'quá trình', không chỉ sản phẩm", "成果物より『過程』を見せましょう", "Tunjukkan 'proses', bukan sekadar hasil"),
      href: "/talent/jobs",
      ctaLabel: t("디자인 직무 공고 보기", "See design job postings", "查看设计职位招聘", "Xem tin tuyển dụng thiết kế", "デザイン職の求人を見る", "Lihat lowongan desain"),
      body: [
        { heading: t("핵심은 '과정'", "The key is 'process'", "关键是『过程』", "Cốt lõi là 'quá trình'", "肝心なのは『過程』", "Kuncinya 'proses'"), text: t("예쁜 결과물만 나열하지 말고, 어떤 문제를 어떻게 풀었는지 과정을 보여주세요. 문제 → 고민 → 결정 → 결과 흐름이 있으면 강해요. 예를 들어 '회원가입 단계가 길어 중간에 그만두는 사람이 많다 → 단계를 줄인 시안 3개 비교 → 친구 5명에게 테스트해 하나 선택' 같은 식이에요. 채용 담당자는 결과물보다 그 사이의 판단을 보고 싶어 해요. 그래서 버린 시안과 그 이유도 숨기지 말고 보여주는 게 좋아요.", "Don't just list pretty results—show how you solved which problems. A problem → deliberation → decision → result flow is powerful. For example: 'Sign-up had too many steps and people quit midway → compared 3 drafts with fewer steps → tested with 5 friends and picked one.' Recruiters want to see the judgment in between more than the final piece. So it's good to show the drafts you discarded and why, rather than hiding them.", "别只罗列漂亮成果，展示你如何解决了什么问题的过程。有『问题→思考→决策→结果』的脉络就很有力。比如『注册步骤太长，很多人中途放弃→比较了3个减少步骤的方案→找5个朋友测试后选定一个』。招聘方比起成果，更想看到中间的判断。所以被放弃的方案和放弃的理由，也最好不要藏起来，一并展示出来。", "Đừng chỉ liệt kê sản phẩm đẹp—hãy cho thấy bạn giải quyết vấn đề nào và như thế nào. Có dòng chảy vấn đề → trăn trở → quyết định → kết quả sẽ mạnh. Ví dụ: 'Bước đăng ký quá dài nên nhiều người bỏ giữa chừng → so sánh 3 phương án rút gọn → thử với 5 người bạn rồi chọn một'. Nhà tuyển dụng muốn thấy những phán đoán ở giữa hơn là sản phẩm cuối. Vì vậy, đừng giấu những phương án đã bỏ và lý do—hãy cho xem cả chúng.", "きれいな成果物を並べるだけでなく、どんな問題をどう解決したか過程を見せましょう。問題→検討→決定→結果の流れがあると強いです。例えば『会員登録の手順が長く途中でやめる人が多い→手順を減らした案を3つ比較→友人5人にテストして一つを選択』といった形です。採用担当者は成果物より、その間の判断を見たいと思っています。だから、捨てた案とその理由も隠さずに見せる方が良いです。", "Jangan hanya memajang hasil cantik—tunjukkan bagaimana Anda memecahkan masalah apa. Alur masalah → pertimbangan → keputusan → hasil itu kuat. Contohnya: 'Langkah pendaftaran terlalu panjang sehingga banyak yang berhenti di tengah → membandingkan 3 rancangan dengan langkah lebih sedikit → menguji ke 5 teman lalu memilih satu'. Perekrut ingin melihat penilaian di antaranya, lebih dari hasil akhirnya. Jadi, sebaiknya tunjukkan juga rancangan yang dibuang beserta alasannya, jangan disembunyikan.") },
        { heading: t("3~4개면 충분", "3–4 is enough", "3~4个就够", "3–4 cái là đủ", "3〜4個で十分", "3–4 sudah cukup"), text: t("많이보다 완성도예요. 자신 있는 3~4개를 깊이 있게 정리하는 게 20개를 얕게 넣는 것보다 낫습니다. 지원하는 직무와 가장 가까운 작업을 맨 앞에 두세요. 앱·웹 서비스 회사라면 UI/UX 사례를, 브랜드 회사라면 아이덴티티 작업을 먼저 보여주는 식으로 순서만 바꿔도 같은 포트폴리오가 훨씬 맞춤형이 돼요. 첫 페이지에는 간단한 자기소개와 관심 분야를 적어 어떤 디자이너인지 한눈에 보이게 해주세요.", "Quality over quantity. Presenting 3–4 you're confident in, in depth, beats putting in 20 shallow ones. Put the work closest to the role you're applying for first. Show UI/UX cases first for an app or web service company, and identity work first for a brand company—just reordering makes the same portfolio feel far more tailored. On the first page, add a brief intro and your areas of interest so people see at a glance what kind of designer you are.", "重质不重量。深入整理3~4个你有信心的，胜过浅显地放20个。把和应聘岗位最接近的作品放在最前面。应聘应用或网站服务公司就先放UI/UX案例，应聘品牌公司就先放品牌识别作品，只是调换顺序，同一份作品集也会显得更有针对性。首页写上简短的自我介绍和关注领域，让人一眼看出你是什么样的设计师。", "Chất hơn lượng. Trình bày sâu 3–4 cái bạn tự tin tốt hơn nhồi 20 cái hời hợt. Hãy đặt dự án gần nhất với vị trí ứng tuyển lên đầu. Với công ty app hoặc web, đưa case UI/UX lên trước; với công ty thương hiệu, đưa dự án nhận diện lên trước—chỉ đổi thứ tự thôi, cùng một portfolio cũng trở nên 'may đo' hơn nhiều. Ở trang đầu, hãy viết giới thiệu ngắn và lĩnh vực quan tâm để người xem nhìn qua là biết bạn là designer thế nào.", "多さより完成度です。自信のある3〜4個を深く整理する方が、20個を浅く入れるより良いです。応募職種に一番近い作品を先頭に置きましょう。アプリ・Webサービスの会社ならUI/UX事例を、ブランドの会社ならアイデンティティの作品を先に見せるように順番を変えるだけで、同じポートフォリオがずっとオーダーメイドになります。最初のページには簡単な自己紹介と関心分野を書き、どんなデザイナーか一目で分かるようにしましょう。", "Kualitas di atas kuantitas. Menyajikan 3–4 yang Anda percaya diri secara mendalam lebih baik daripada 20 yang dangkal. Taruh karya yang paling dekat dengan posisi yang dilamar di urutan pertama. Untuk perusahaan aplikasi atau web, tampilkan studi kasus UI/UX lebih dulu; untuk perusahaan merek, tampilkan karya identitas lebih dulu—cukup ubah urutan, portofolio yang sama terasa jauh lebih disesuaikan. Di halaman pertama, tulis perkenalan singkat dan bidang minat agar orang langsung tahu Anda desainer seperti apa.") },
        { heading: t("한 프로젝트 구성법", "Structuring one project", "单个项目怎么组织", "Cấu trúc một dự án", "1プロジェクトの構成", "Menyusun satu proyek"), text: t("프로젝트 하나는 이렇게 구성해보세요.\n· 한 줄 요약과 내 역할\n· 문제 정의와 대상 사용자\n· 리서치·스케치 등 고민의 흔적\n· 최종 결과와 그렇게 결정한 이유\n· 배운 점이나 다음에 바꾸고 싶은 점\n팀 작업이라면 내가 맡은 부분을 분명히 적어야 오해가 없어요. 이 순서를 지키면 처음 보는 사람도 몇 분 안에 흐름을 따라올 수 있어요.", "Try structuring each project like this:\n· A one-line summary and your role\n· The problem and target users\n· Traces of your thinking, like research and sketches\n· The final result and why you chose it\n· What you learned or would change next time\nFor team work, clearly state which part was yours to avoid misunderstandings. Following this order lets even a first-time viewer follow the flow within a few minutes.", "一个项目可以这样组织：\n· 一句话概括和你的角色\n· 问题定义和目标用户\n· 调研、草图等思考痕迹\n· 最终结果以及这样决定的理由\n· 收获或下次想改进的地方\n如果是团队作品，要写清楚你负责的部分，避免误会。按这个顺序来，第一次看的人也能在几分钟内跟上思路。", "Hãy thử cấu trúc mỗi dự án như sau:\n· Tóm tắt một dòng và vai trò của bạn\n· Định nghĩa vấn đề và người dùng mục tiêu\n· Dấu vết suy nghĩ như nghiên cứu, phác thảo\n· Kết quả cuối và lý do quyết định như vậy\n· Điều đã học hoặc muốn thay đổi lần sau\nNếu là làm nhóm, hãy ghi rõ phần bạn phụ trách để tránh hiểu lầm. Theo thứ tự này, ngay cả người xem lần đầu cũng nắm được mạch trong vài phút.", "プロジェクト一つはこう構成してみましょう。\n・一行の要約と自分の役割\n・問題の定義と対象ユーザー\n・リサーチ・スケッチなど検討の跡\n・最終結果とそう決めた理由\n・学んだことや次に変えたい点\nチーム作業なら、自分が担当した部分をはっきり書くと誤解がありません。この順番を守れば、初めて見る人も数分で流れを追えます。", "Coba susun tiap proyek seperti ini:\n· Ringkasan satu kalimat dan peran Anda\n· Definisi masalah dan pengguna sasaran\n· Jejak pemikiran seperti riset dan sketsa\n· Hasil akhir dan alasan memilihnya\n· Pelajaran atau hal yang ingin diubah lain kali\nUntuk kerja tim, tulis jelas bagian yang Anda kerjakan agar tidak salah paham. Dengan urutan ini, orang yang baru pertama melihat pun bisa mengikuti alurnya dalam beberapa menit.") },
        { heading: t("자주 하는 실수", "Common mistakes", "常见错误", "Lỗi thường gặp", "よくある失敗", "Kesalahan umum"), text: t("가장 흔한 실수는 설명 없이 이미지만 이어 붙이는 거예요. 보는 사람은 왜 이런 디자인이 나왔는지 알 수 없어요. 반대로 글이 너무 길어도 끝까지 읽히지 않으니, 핵심 문장은 굵게 하고 흐름은 이미지로 보여주세요. 파일이 너무 무겁거나 링크가 열리지 않는 경우도 많으니, 제출 전에 다른 기기에서 꼭 열어보세요. 오탈자나 정렬이 어긋난 부분도 꼼꼼함을 보여주는 신호이니 마지막에 한 번 더 확인하세요.", "The most common mistake is stringing images together with no explanation—viewers can't tell why the design turned out that way. On the other hand, too much text won't get read to the end, so bold the key sentences and show the flow with images. Files that are too heavy or links that don't open are also common, so always open it on another device before submitting. Typos and misaligned elements are also signals of attention to detail, so check once more at the end.", "最常见的错误是不加说明、只把图片拼在一起，看的人无法知道为什么会是这样的设计。反过来文字太长也没人读完，所以把关键句加粗，用图片展示流程。文件太大或链接打不开的情况也很多，提交前一定要在别的设备上打开看看。错别字和没对齐的地方也反映细致程度，最后再检查一遍。", "Lỗi phổ biến nhất là ghép ảnh liên tiếp mà không giải thích—người xem không hiểu vì sao lại ra thiết kế như vậy. Ngược lại, chữ quá dài cũng không ai đọc hết, nên hãy in đậm câu chính và thể hiện luồng bằng hình ảnh. File quá nặng hoặc link không mở được cũng hay gặp, nên trước khi nộp hãy mở thử trên thiết bị khác. Lỗi chính tả hay căn chỉnh lệch cũng phản ánh sự tỉ mỉ, nên hãy kiểm tra lại lần cuối.", "最もよくある失敗は、説明なしで画像だけをつなげることです。見る人はなぜこのデザインになったのか分かりません。逆に文章が長すぎても最後まで読まれないので、要点の文は太字にし、流れは画像で見せましょう。ファイルが重すぎたりリンクが開かなかったりすることも多いので、提出前に別の端末で必ず開いてみましょう。誤字や揃っていない部分も几帳面さを示すサインなので、最後にもう一度確認しましょう。", "Kesalahan paling umum adalah menempel gambar berurutan tanpa penjelasan—orang yang melihat tidak tahu mengapa desainnya begitu. Sebaliknya, teks yang terlalu panjang juga tak akan dibaca sampai habis, jadi tebalkan kalimat inti dan tunjukkan alurnya lewat gambar. File yang terlalu berat atau tautan yang tak bisa dibuka juga sering terjadi, jadi buka dulu di perangkat lain sebelum mengirim. Salah ketik dan elemen yang tidak rata juga menunjukkan ketelitian, jadi periksa sekali lagi di akhir.") },
        { heading: t("실무 경험이 없다면", "If you lack work experience", "如果没有实务经验", "Nếu chưa có kinh nghiệm", "実務経験がないなら", "Jika belum ada pengalaman kerja"), text: t("회사 프로젝트가 없어도 괜찮아요. 자주 쓰는 앱의 불편한 점을 찾아 개선안을 만들어보는 '리디자인' 작업도 좋은 재료예요. 이때 '원래 화면의 문제 → 내가 바꾼 점 → 기대하는 효과'를 함께 적으면 실무형 사고를 보여줄 수 있어요. 유학생이라면 모국과 한국 앱의 차이를 비교한 사례처럼 나만의 시각이 담긴 주제도 눈에 띄어요. 실제 사용자 몇 명에게 의견을 들어본 과정까지 담으면 더 설득력 있어요.", "It's fine if you don't have company projects. A 'redesign'—finding pain points in an app you use often and proposing improvements—is great material. Write down 'the problem with the original screen → what you changed → the expected effect' to show work-ready thinking. If you're an international student, topics with your own perspective, like comparing apps in your home country and Korea, also stand out. Including how you gathered feedback from a few real users makes it even more convincing.", "没有公司项目也没关系。找出常用应用的不便之处并做出改进方案的『重新设计』也是很好的素材。同时写上『原界面的问题→你的改动→预期效果』，就能展现实务型思维。如果你是留学生，比较本国和韩国应用差异这类带有自己视角的主题也很显眼。如果再加上向几位真实用户征求意见的过程，会更有说服力。", "Không có dự án công ty cũng không sao. Làm 'redesign'—tìm điểm bất tiện trong ứng dụng hay dùng và đề xuất cải thiện—cũng là chất liệu tốt. Hãy ghi kèm 'vấn đề của màn hình gốc → điều bạn thay đổi → hiệu quả kỳ vọng' để thể hiện tư duy thực tế. Nếu là du học sinh, những chủ đề mang góc nhìn riêng như so sánh ứng dụng ở quê nhà và Hàn Quốc cũng rất nổi bật. Nếu thêm cả quá trình hỏi ý kiến vài người dùng thật, sẽ càng thuyết phục hơn.", "会社のプロジェクトがなくても大丈夫です。よく使うアプリの不便な点を見つけて改善案を作る『リデザイン』も良い材料です。その際『元の画面の問題→自分が変えた点→期待する効果』を一緒に書くと、実務的な思考を見せられます。留学生なら、母国と韓国のアプリの違いを比べた事例のように、自分ならではの視点がこもったテーマも目を引きます。実際のユーザー数人に意見を聞いた過程まで入れると、さらに説得力が増します。", "Tidak punya proyek perusahaan pun tidak apa-apa. 'Redesign'—menemukan kekurangan aplikasi yang sering dipakai lalu membuat usulan perbaikan—juga materi yang bagus. Tulis sekalian 'masalah layar asli → yang Anda ubah → efek yang diharapkan' untuk menunjukkan cara berpikir siap kerja. Jika Anda mahasiswa asing, topik dengan sudut pandang sendiri, seperti membandingkan aplikasi di negara asal dan Korea, juga menonjol. Menyertakan proses meminta pendapat beberapa pengguna nyata membuatnya makin meyakinkan.") },
        { heading: t("이런 사람에게", "A good fit for", "适合这样的人", "Phù hợp với", "こんな人に", "Cocok untuk"), text: t("사용자의 불편을 발견하고 더 나은 경험으로 바꾸는 데 흥미가 있는 사람에게 잘 맞아요. 디자이너는 혼자 그리는 사람이 아니라 기획자·개발자와 계속 이야기하며 맞춰가는 사람이에요. 그래서 내 디자인을 말로 설명하는 연습도 중요해요. 포트폴리오의 각 프로젝트를 1분 안에 소개해보는 것부터 시작해보세요. 설명이 막히는 부분이 있다면 그 프로젝트의 과정 정리가 더 필요하다는 신호예요.", "Great for people interested in spotting user pain points and turning them into better experiences. Designers don't draw alone—they keep talking and aligning with planners and developers. That's why practicing explaining your design in words matters too. Start by trying to introduce each portfolio project in under a minute. If you get stuck explaining a part, that's a sign the project's process needs more organizing.", "适合对发现用户的不便、并将其转化为更好体验感兴趣的人。设计师不是一个人埋头画图，而是不断与策划、开发沟通、磨合的人。所以练习用语言解释自己的设计也很重要。可以先从用1分钟介绍作品集里的每个项目开始。如果讲到某处卡住了，说明这个项目的过程还需要再梳理。", "Rất hợp với người hứng thú phát hiện điểm bất tiện của người dùng và biến thành trải nghiệm tốt hơn. Designer không vẽ một mình mà liên tục trao đổi, điều chỉnh cùng planner và lập trình viên. Vì vậy luyện cách giải thích thiết kế bằng lời cũng rất quan trọng. Hãy bắt đầu bằng việc giới thiệu mỗi dự án trong portfolio trong vòng 1 phút. Nếu bị vướng khi giải thích phần nào, đó là dấu hiệu quá trình của dự án cần được sắp xếp thêm.", "ユーザーの不便を見つけ、より良い体験に変えることに興味がある人によく合います。デザイナーは一人で描く人ではなく、企画者・開発者と話し合いながら合わせていく人です。だから自分のデザインを言葉で説明する練習も大切です。ポートフォリオの各プロジェクトを1分以内で紹介してみることから始めましょう。説明に詰まる部分があれば、そのプロジェクトの過程の整理がもっと必要だというサインです。", "Cocok bagi yang tertarik menemukan keluhan pengguna dan mengubahnya jadi pengalaman lebih baik. Desainer tidak menggambar sendirian—mereka terus berdiskusi dan menyelaraskan dengan planner dan developer. Karena itu, berlatih menjelaskan desain dengan kata-kata juga penting. Mulailah dengan mencoba memperkenalkan tiap proyek portofolio dalam waktu kurang dari satu menit. Jika Anda tersendat saat menjelaskan suatu bagian, itu tanda proses proyek tersebut perlu dirapikan lagi.") }
      ]
    },
    {
      slug: "product-manager",
      emoji: "📝",
      title: t("기획·PM은\n무슨 일을 하나요?", "What does a\nplanner/PM do?", "策划·PM\n做什么工作？", "Planner/PM\nlàm gì?", "企画・PMは\n何をしますか？", "Apa yang dilakukan\nplanner/PM?"),
      desc: t("만드는 사람들을 잇는 역할", "The role that connects the makers", "连接创造者们的角色", "Vai trò kết nối những người tạo ra sản phẩm", "作る人たちをつなぐ役割", "Peran yang menghubungkan para pembuat"),
      href: "/talent/jobs",
      ctaLabel: t("기획 직무 공고 보기", "See planning job postings", "查看策划职位招聘", "Xem tin tuyển dụng planning", "企画職の求人を見る", "Lihat lowongan planning"),
      body: [
        { heading: t("하는 일", "What they do", "工作内容", "Công việc", "する仕事", "Yang dikerjakan"), text: t("'무엇을 왜 만들지'를 정하고, 개발·디자인·마케팅이 같은 방향을 보게 조율해요. 우선순위를 정하고 일정을 챙기는 게 큰 몫이에요. 회사에 따라 서비스 기획, 프로덕트 매니저, 프로젝트 매니저처럼 이름과 범위가 조금씩 달라요. 공통점은 직접 만들기보다 '잘 만들어지도록 판단하고 연결하는' 역할이라는 점이에요. 그래서 신입에게는 화려한 아이디어보다 꼼꼼함과 소통 능력이 먼저 보여요.", "They decide 'what to build and why' and align development, design, and marketing toward the same direction. Setting priorities and managing schedules is a big part. Depending on the company, the title and scope vary a little—service planner, product manager, project manager. What they share: rather than building things themselves, they make the calls and connect people so things get built well. So for newcomers, thoroughness and communication skills stand out before flashy ideas.", "决定『做什么、为什么做』，并协调开发、设计、营销朝同一方向。定优先级、盯进度是很大一部分。不同公司叫法和范围略有不同，比如服务策划、产品经理、项目经理。共同点是，比起亲手做，更多是『做判断、做连接，让东西被做好』的角色。所以对新人来说，比起花哨的点子，细致和沟通能力更先被看到。", "Họ quyết định 'làm gì và vì sao' và điều phối để phát triển, thiết kế, marketing cùng hướng. Đặt ưu tiên và quản lý tiến độ là phần lớn công việc. Tùy công ty mà tên gọi và phạm vi hơi khác nhau, như service planner, product manager, project manager. Điểm chung là thay vì tự tay làm, họ 'ra quyết định và kết nối để sản phẩm được làm tốt'. Vì vậy với người mới, sự tỉ mỉ và khả năng giao tiếp được chú ý trước những ý tưởng hào nhoáng.", "『何をなぜ作るか』を決め、開発・デザイン・マーケティングが同じ方向を向くよう調整します。優先順位を決め、日程を管理するのが大きな役割です。会社によってサービス企画、プロダクトマネージャー、プロジェクトマネージャーなど名前と範囲が少しずつ違います。共通点は、自分で作るより『うまく作られるように判断し、つなぐ』役割だということです。だから新人には、華やかなアイデアより几帳面さとコミュニケーション力が先に見られます。", "Mereka menentukan 'apa yang dibuat dan mengapa' serta menyelaraskan pengembangan, desain, dan pemasaran ke arah yang sama. Menetapkan prioritas dan mengatur jadwal adalah bagian besarnya. Tergantung perusahaan, nama dan cakupannya sedikit berbeda—service planner, product manager, project manager. Kesamaannya: alih-alih membuat sendiri, mereka mengambil keputusan dan menghubungkan orang agar produk dibuat dengan baik. Karena itu, bagi pemula, ketelitian dan kemampuan komunikasi lebih dulu dilihat daripada ide yang mencolok.") },
        { heading: t("기획자의 하루", "A planner's day", "策划的一天", "Một ngày của planner", "企画者の一日", "Sehari seorang planner"), text: t("하루는 회의와 문서가 많은 편이에요. 사용자 의견이나 데이터를 보고 문제를 찾고, 해결 방향을 정리한 기획서나 화면 설계서를 써요. 그다음 개발자·디자이너와 범위와 일정을 맞추고, 진행 중에 생기는 질문에 답하며 결정을 내려요. 출시 후에는 사용자 반응을 확인하고 다음에 고칠 점을 정리하는 일이 이어져요. 하루 중 상당 시간이 '확인하고 맞추는 일'이라 꼼꼼한 기록 습관이 큰 힘이 돼요.", "The day tends to be full of meetings and documents. You look at user feedback or data to find problems, then write a plan or screen spec outlining the solution. Next you align scope and schedule with developers and designers, answering questions and making decisions as work progresses. After launch, you check how users respond and list what to fix next. Much of the day is 'checking and aligning,' so a habit of careful note-taking is a big asset.", "一天里会议和文档比较多。看用户反馈或数据找问题，然后写出整理好解决方向的策划书或界面设计文档。接着和开发、设计对齐范围与日程，在推进中回答各种问题并做决定。上线后还要查看用户反应，整理下一步要改的地方。一天中相当多的时间都在『确认和对齐』，所以细致的记录习惯非常有用。", "Một ngày thường có nhiều cuộc họp và tài liệu. Bạn xem ý kiến người dùng hoặc dữ liệu để tìm vấn đề, rồi viết bản kế hoạch hoặc tài liệu thiết kế màn hình nêu hướng giải quyết. Tiếp theo, bạn thống nhất phạm vi và tiến độ với lập trình viên, designer, trả lời câu hỏi và ra quyết định trong quá trình làm. Sau khi ra mắt, bạn xem phản ứng người dùng và ghi lại điểm cần sửa tiếp. Phần lớn thời gian trong ngày là 'kiểm tra và thống nhất', nên thói quen ghi chép cẩn thận là lợi thế lớn.", "一日は会議と文書が多めです。ユーザーの声やデータを見て問題を見つけ、解決の方向をまとめた企画書や画面設計書を書きます。次に開発者・デザイナーと範囲と日程を合わせ、進行中に出てくる質問に答えながら決定を下します。リリース後はユーザーの反応を確認し、次に直す点を整理する仕事が続きます。一日のかなりの時間が『確認してすり合わせる仕事』なので、丁寧に記録する習慣が大きな力になります。", "Harinya cenderung penuh rapat dan dokumen. Anda melihat masukan pengguna atau data untuk menemukan masalah, lalu menulis dokumen rencana atau spesifikasi layar yang merangkum arah solusinya. Selanjutnya Anda menyelaraskan cakupan dan jadwal dengan developer dan desainer, menjawab pertanyaan dan mengambil keputusan selama proses. Setelah rilis, Anda memeriksa respons pengguna dan mencatat apa yang perlu diperbaiki berikutnya. Sebagian besar hari diisi 'mengecek dan menyelaraskan', jadi kebiasaan mencatat dengan rapi sangat membantu.") },
        { heading: t("꼭 필요한 역량", "Must-have skills", "必备能力", "Năng lực cần có", "必要な力", "Kemampuan wajib"), text: t("가장 중요한 건 '글로 정리하는 힘'과 '설득하는 힘'이에요. 복잡한 상황을 누구나 이해할 수 있게 문서로 정리하고, 왜 이게 먼저인지 근거를 들어 설명해야 해요. 기본적인 데이터 읽기와 개발·디자인 과정에 대한 이해도 큰 도움이 돼요. 코딩을 직접 할 필요는 없지만, 개발자가 무엇을 고민하는지 알면 대화가 훨씬 쉬워져요. 회의 내용을 깔끔하게 정리해 공유하는 것처럼 작은 습관에서부터 이 역량이 드러나요.", "The most important are 'the ability to organize in writing' and 'the ability to persuade.' You need to turn complex situations into documents anyone can understand and explain with evidence why something comes first. Basic data literacy and an understanding of how development and design work also help a lot. You don't need to code yourself, but knowing what developers worry about makes conversations much easier. These skills show up in small habits, like neatly summarizing and sharing meeting notes.", "最重要的是『用文字梳理的能力』和『说服的能力』。要把复杂的情况整理成谁都能看懂的文档，并有理有据地说明为什么这个优先。基本的数据解读能力、对开发和设计流程的理解也很有帮助。不需要自己写代码，但了解开发在纠结什么，沟通会轻松很多。这些能力会从小习惯中体现出来，比如把会议内容整理清楚并分享出去。", "Quan trọng nhất là 'khả năng sắp xếp bằng văn bản' và 'khả năng thuyết phục'. Bạn cần biến tình huống phức tạp thành tài liệu ai cũng hiểu, và giải thích có căn cứ vì sao việc này cần làm trước. Khả năng đọc dữ liệu cơ bản và hiểu quy trình phát triển, thiết kế cũng giúp ích rất nhiều. Không cần tự code, nhưng biết lập trình viên trăn trở điều gì sẽ giúp trao đổi dễ hơn nhiều. Những năng lực này thể hiện từ thói quen nhỏ, như tóm tắt gọn gàng và chia sẻ nội dung cuộc họp.", "最も大切なのは『文章で整理する力』と『説得する力』です。複雑な状況を誰でも分かるように文書にまとめ、なぜこれが先なのか根拠を挙げて説明する必要があります。基本的なデータの読み方や、開発・デザインの進め方への理解も大きな助けになります。自分でコーディングする必要はありませんが、開発者が何に悩んでいるかを知ると会話がずっと楽になります。会議の内容をきれいにまとめて共有するような小さな習慣から、この力は表れます。", "Yang terpenting adalah 'kemampuan merangkum lewat tulisan' dan 'kemampuan meyakinkan'. Anda perlu mengubah situasi rumit menjadi dokumen yang mudah dipahami siapa pun dan menjelaskan dengan dasar mengapa sesuatu didahulukan. Kemampuan dasar membaca data serta pemahaman proses pengembangan dan desain juga sangat membantu. Anda tak perlu ngoding sendiri, tapi tahu apa yang dipikirkan developer membuat komunikasi jauh lebih mudah. Kemampuan ini terlihat dari kebiasaan kecil, seperti merangkum dan membagikan isi rapat dengan rapi.") },
        { heading: t("준비하면 좋은 것", "Good to prepare", "值得准备的", "Nên chuẩn bị", "準備すると良いもの", "Baik untuk disiapkan"), text: t("동아리·팀플에서 '이끌어 본 경험'을 정리하세요. 왜 그 결정을 했고 어떤 결과가 나왔는지 설명할 수 있으면 좋아요. 여기에 자주 쓰는 앱 하나를 골라 '불편한 점 → 개선 아이디어 → 성과를 확인할 지표'를 짧은 기획서로 만들어보는 걸 추천해요. 예를 들어 '검색 결과가 너무 많다 → 필터 추가 → 검색 후 클릭률로 확인'처럼요. 완벽할 필요는 없고, 생각의 흐름이 보이면 충분해요.", "Organize times you 'led' in clubs or team projects. It helps if you can explain why you made a decision and what result it produced. We also recommend picking an app you use often and writing a short plan: 'pain point → improvement idea → metric to check the result.' For example: 'Too many search results → add filters → check the click rate after searching.' It doesn't need to be perfect—showing your line of thinking is enough.", "整理你在社团、团队项目中『带领过的经验』。能说明为何做那个决定、产生了什么结果就更好。另外推荐挑一个常用的应用，写一份简短的策划：『不便之处→改进点子→用来验证效果的指标』。比如『搜索结果太多→增加筛选→用搜索后的点击率来验证』。不需要完美，能看出思路就足够了。", "Hãy sắp xếp những lần bạn 'dẫn dắt' trong câu lạc bộ hay dự án nhóm. Sẽ tốt nếu bạn giải thích được vì sao ra quyết định đó và kết quả ra sao. Ngoài ra, hãy chọn một ứng dụng hay dùng và viết bản kế hoạch ngắn: 'điểm bất tiện → ý tưởng cải thiện → chỉ số để kiểm tra kết quả'. Ví dụ: 'Kết quả tìm kiếm quá nhiều → thêm bộ lọc → kiểm tra bằng tỷ lệ nhấp sau khi tìm kiếm'. Không cần hoàn hảo—chỉ cần thấy được mạch suy nghĩ là đủ.", "サークル・チームプロジェクトで『引っ張った経験』を整理しましょう。なぜその決定をし、どんな結果が出たか説明できると良いです。さらに、よく使うアプリを一つ選び、『不便な点→改善アイデア→成果を確かめる指標』を短い企画書にしてみるのがおすすめです。例えば『検索結果が多すぎる→フィルター追加→検索後のクリック率で確認』のようにです。完璧である必要はなく、考えの流れが見えれば十分です。", "Rapikan pengalaman Anda 'memimpin' di klub atau proyek tim. Akan bagus bila bisa menjelaskan mengapa mengambil keputusan itu dan hasilnya apa. Kami juga menyarankan memilih satu aplikasi yang sering dipakai lalu menulis rencana singkat: 'masalah → ide perbaikan → metrik untuk mengecek hasil'. Contohnya: 'Hasil pencarian terlalu banyak → tambah filter → cek lewat rasio klik setelah mencari'. Tidak perlu sempurna—cukup jika alur pikir Anda terlihat.") },
        { heading: t("면접에서 보는 것", "What interviewers look for", "面试看什么", "Nhà tuyển dụng xem gì", "面接で見られること", "Yang dilihat pewawancara"), text: t("기획 면접에서는 '이 서비스의 문제는 뭐라고 생각하나요?', '두 기능 중 하나만 만들 수 있다면?' 같은 질문이 자주 나와요. 정답보다 판단 기준을 묻는 질문이라, 사용자·목표·자원을 근거로 차분히 설명하는 게 좋아요. 의견이 부딪혔던 경험을 묻는다면 어떻게 대화하고 합의했는지를 구체적으로 이야기해보세요. 면접 전에 지원 회사의 서비스를 직접 써보고 한두 가지 개선점을 생각해두면 대화가 훨씬 수월해요.", "Planning interviews often ask things like 'What do you think is wrong with this service?' or 'If you could build only one of these two features, which one?' These questions are about your decision criteria, not a right answer, so calmly explain based on users, goals, and resources. If asked about a time opinions clashed, describe specifically how you talked it through and reached agreement. Using the company's service before the interview and thinking of one or two improvements makes the conversation much smoother.", "策划面试常问『你觉得这个服务的问题是什么？』『两个功能只能做一个的话选哪个？』这类问题。它们考察的是判断标准而非标准答案，所以要以用户、目标、资源为依据冷静说明。如果被问到意见冲突的经历，就具体讲讲你是怎样沟通并达成一致的。面试前亲自用一用应聘公司的服务，想好一两个改进点，交流会顺畅得多。", "Phỏng vấn planning thường hỏi 'Bạn nghĩ dịch vụ này có vấn đề gì?' hay 'Nếu chỉ làm được một trong hai tính năng thì chọn cái nào?'. Đây là câu hỏi về tiêu chí phán đoán chứ không phải đáp án đúng, nên hãy bình tĩnh giải thích dựa trên người dùng, mục tiêu và nguồn lực. Nếu được hỏi về lần bất đồng ý kiến, hãy kể cụ thể bạn đã trao đổi và đi đến thống nhất ra sao. Trước buổi phỏng vấn, hãy tự dùng dịch vụ của công ty và nghĩ sẵn một hai điểm cải thiện để cuộc trò chuyện suôn sẻ hơn.", "企画の面接では『このサービスの問題は何だと思いますか?』『二つの機能のうち一つしか作れないなら?』といった質問がよく出ます。正解より判断基準を問う質問なので、ユーザー・目標・リソースを根拠に落ち着いて説明するのが良いです。意見がぶつかった経験を聞かれたら、どう話し合って合意したかを具体的に話しましょう。面接前に応募企業のサービスを実際に使い、改善点を一つ二つ考えておくと、会話がずっとスムーズになります。", "Wawancara planning sering menanyakan 'Menurut Anda apa masalah layanan ini?' atau 'Jika hanya bisa membuat salah satu dari dua fitur, pilih yang mana?'. Pertanyaan ini menguji kriteria keputusan, bukan jawaban benar, jadi jelaskan dengan tenang berdasarkan pengguna, tujuan, dan sumber daya. Jika ditanya pengalaman berbeda pendapat, ceritakan secara spesifik bagaimana Anda berdiskusi dan mencapai kesepakatan. Mencoba layanan perusahaan sebelum wawancara dan memikirkan satu dua perbaikan membuat percakapan jauh lebih lancar.") },
        { heading: t("이런 사람에게", "A good fit for", "适合这样的人", "Phù hợp với", "こんな人に", "Cocok untuk"), text: t("큰 그림을 그리면서 사람들을 조율하고, 우선순위를 정하는 걸 잘하는 사람에게 잘 맞아요. 여러 사람의 이야기를 듣고 공통점을 찾는 걸 좋아한다면 더욱 그래요. 유학생이라면 해외 사용자를 이해하는 시각과 다양한 문화 경험이 글로벌 서비스 기획에서 장점이 될 수 있어요. 다만 문서와 회의가 많은 만큼 업무 한국어도 함께 준비해두세요. 작은 기획서 하나를 직접 써보는 것부터 시작해보세요.", "Great for people good at seeing the big picture, coordinating people, and setting priorities—especially if you enjoy listening to many voices and finding common ground. For international students, an eye for overseas users and diverse cultural experience can be an advantage in planning global services. Since the job involves lots of documents and meetings, prepare your workplace Korean as well. Start by writing one small plan yourself.", "适合擅长描绘大局、协调众人、确定优先级的人。如果你喜欢倾听不同人的想法并找到共同点，就更合适了。如果你是留学生，理解海外用户的视角和多元文化经历，在全球化服务策划中可能成为优势。不过这份工作文档和会议多，职场韩语也要一起准备。先从亲手写一份小策划书开始吧。", "Rất hợp với người giỏi nhìn bức tranh lớn, điều phối mọi người và đặt ưu tiên—nhất là nếu bạn thích lắng nghe nhiều ý kiến và tìm điểm chung. Với du học sinh, góc nhìn hiểu người dùng nước ngoài và trải nghiệm đa văn hóa có thể là lợi thế khi lên kế hoạch dịch vụ toàn cầu. Tuy nhiên công việc có nhiều tài liệu và họp, nên hãy chuẩn bị cả tiếng Hàn công sở. Hãy bắt đầu bằng việc tự viết một bản kế hoạch nhỏ.", "大きな絵を描きながら人を調整し、優先順位を決めるのが得意な人によく合います。いろいろな人の話を聞いて共通点を見つけるのが好きなら、なおさらです。留学生なら、海外ユーザーを理解する視点や多様な文化経験が、グローバルサービスの企画で強みになり得ます。ただし文書や会議が多い分、ビジネス韓国語も一緒に準備しておきましょう。まずは小さな企画書を一つ自分で書いてみることから始めましょう。", "Cocok bagi yang mahir melihat gambaran besar, mengoordinasikan orang, dan menetapkan prioritas—terutama jika Anda senang mendengarkan banyak pendapat dan mencari titik temu. Bagi mahasiswa asing, cara pandang yang memahami pengguna luar negeri dan pengalaman lintas budaya bisa menjadi keunggulan dalam merancang layanan global. Namun karena banyak dokumen dan rapat, siapkan juga bahasa Korea untuk kerja. Mulailah dengan menulis sendiri satu dokumen rencana kecil.") }
      ]
    }
  ];
}

// 취업 노하우 — 첫 취업에서 자주 막히는 지점을 풀어주는 실전 팁.
export function jobHunting(t: PlatformT): CareerGuide[] {
  return [
    {
      slug: "choosing-first-job",
      emoji: "🧭",
      title: t("첫 직장,\n어떻게 고르죠?", "How to choose\nyour first job?", "第一份工作\n怎么选？", "Chọn công việc\nđầu tiên thế nào?", "初めての職場、\nどう選ぶ？", "Bagaimana memilih\npekerjaan pertama?"),
      desc: t("연봉 말고 이걸 먼저 보세요", "Look at this before salary", "别只看薪资，先看这些", "Hãy xem điều này trước lương", "年収より先にこれを見て", "Lihat ini sebelum gaji"),
      body: [
        { heading: t("'무슨 일'을 하는지", "'What work' you'll do", "做『什么工作』", "Bạn làm 'việc gì'", "『どんな仕事』をするか", "'Pekerjaan apa' yang dilakukan"), text: t("회사 이름·연봉보다, 내가 매일 하게 될 '주요 업무'가 끌리는지가 오래 다니는 데 가장 중요해요. 공고의 주요 업무 항목을 한 줄씩 읽으며 '이걸 1년 동안 매일 해도 괜찮을까?'라고 스스로 물어보세요. 직무 이름이 같아도 회사마다 실제로 하는 일은 꽤 달라서, 이름보다 업무 내용을 보는 게 정확해요. 가능하다면 그 직무에서 일하는 사람의 이야기를 찾아보는 것도 큰 도움이 돼요.", "More than the company name or salary, whether the 'key duties' you'd do daily appeal to you matters most for staying long. Read the posting's key duties line by line and ask yourself, 'Would I be okay doing this every day for a year?' Even with the same job title, the actual work differs quite a bit between companies, so looking at the duties is more accurate than the title. If you can, looking up stories from people working in that role helps a lot.", "比起公司名和薪资，你每天要做的『主要工作』是否吸引你，对能否长久最重要。把招聘里的主要工作逐条读一遍，问问自己：『这件事每天做、做一年，我能接受吗？』即使职位名称相同，不同公司实际做的事也差别不小，所以看工作内容比看职位名更准确。如果可以，找找在这个岗位工作的人的分享，也会很有帮助。", "Hơn cả tên công ty hay lương, việc 'nhiệm vụ chính' hằng ngày có hấp dẫn không mới quan trọng nhất để gắn bó lâu. Hãy đọc từng dòng mục nhiệm vụ chính trong tin tuyển dụng và tự hỏi 'Mình có ổn khi làm việc này mỗi ngày trong một năm không?'. Dù cùng tên vị trí, công việc thực tế mỗi công ty khá khác nhau, nên xem nội dung công việc sẽ chính xác hơn tên gọi. Nếu có thể, tìm đọc chia sẻ của người đang làm vị trí đó cũng giúp ích rất nhiều.", "会社名・年収より、自分が毎日する『主な業務』に惹かれるかが長く続けるうえで最も大切です。求人の主な業務を一行ずつ読みながら『これを1年間毎日やっても大丈夫か?』と自分に問いかけてみましょう。職種名が同じでも会社ごとに実際の仕事はかなり違うので、名前より業務内容を見る方が正確です。可能なら、その職務で働く人の話を探してみるのも大きな助けになります。", "Lebih dari nama perusahaan atau gaji, apakah 'tugas utama' harian menarik bagi Anda paling penting untuk bertahan lama. Baca bagian tugas utama di lowongan baris demi baris dan tanyakan pada diri sendiri, 'Apakah saya sanggup melakukan ini setiap hari selama setahun?'. Meski nama posisinya sama, pekerjaan nyatanya cukup berbeda antarperusahaan, jadi melihat isi tugas lebih akurat daripada namanya. Jika bisa, mencari cerita dari orang yang bekerja di posisi itu juga sangat membantu.") },
        { heading: t("성장 환경인지", "Is it a place to grow", "是否是成长环境", "Có phải môi trường phát triển", "成長できる環境か", "Apakah lingkungan untuk berkembang"), text: t("첫 직장은 배우는 곳이에요. 사수가 있는지, 피드백을 받을 수 있는지, 새로운 걸 시도해볼 수 있는지를 보세요. 면접 마지막에 '궁금한 점 있나요?'라고 물으면 '입사하면 처음 3개월 동안 어떤 일을 하게 되나요?', '팀에서는 피드백을 어떻게 주고받나요?'처럼 물어보세요. 대답을 들으면 분위기를 꽤 알 수 있어요. 첫 1~2년 동안 무엇을 배울 수 있는지가 다음 커리어의 출발선을 정해요.", "A first job is a place to learn. Check if there's a mentor, whether you can get feedback, and whether you can try new things. When they ask 'Any questions?' at the end of the interview, try asking 'What would I work on in my first three months?' or 'How does the team give and receive feedback?' The answers tell you a lot about the atmosphere. What you can learn in your first year or two sets the starting line for your next career step.", "第一份工作是学习的地方。看看有没有带你的前辈、能否获得反馈、能否尝试新事物。面试最后被问『有什么想问的吗？』时，可以问『入职后前三个月会做哪些工作？』『团队里是怎样给反馈的？』。听了回答，就能大致了解团队氛围。头一两年能学到什么，决定了下一段职业的起点。", "Công việc đầu tiên là nơi để học. Hãy xem có người hướng dẫn không, có nhận được phản hồi không, có thể thử điều mới không. Khi cuối buổi phỏng vấn được hỏi 'Bạn có câu hỏi nào không?', hãy hỏi 'Ba tháng đầu tôi sẽ làm những việc gì?' hay 'Nhóm trao đổi phản hồi với nhau thế nào?'. Nghe câu trả lời là bạn hiểu khá rõ bầu không khí. Những gì bạn học được trong 1–2 năm đầu sẽ quyết định vạch xuất phát cho bước sự nghiệp tiếp theo.", "初めての職場は学ぶ場所です。指導してくれる先輩がいるか、フィードバックを受けられるか、新しいことを試せるかを見ましょう。面接の最後に『何か質問はありますか?』と聞かれたら、『入社後の最初の3か月はどんな仕事をしますか?』『チームではフィードバックをどうやり取りしていますか?』と聞いてみましょう。答えから雰囲気がかなり分かります。最初の1〜2年で何を学べるかが、次のキャリアのスタートラインを決めます。", "Pekerjaan pertama adalah tempat belajar. Cek apakah ada mentor, bisa dapat umpan balik, dan bisa mencoba hal baru. Saat ditanya 'Ada pertanyaan?' di akhir wawancara, coba tanyakan 'Apa yang akan saya kerjakan di tiga bulan pertama?' atau 'Bagaimana tim saling memberi umpan balik?'. Jawabannya banyak menunjukkan suasana tim. Apa yang bisa Anda pelajari di satu dua tahun pertama menentukan garis start karier berikutnya.") },
        { heading: t("함께 일할 사람들", "The people you'll work with", "一起工作的人", "Những người làm cùng", "一緒に働く人たち", "Orang-orang yang bekerja bersama"), text: t("같은 일이라도 누구와 하느냐에 따라 경험이 크게 달라져요. 면접에서 만난 사람들의 태도, 질문하는 방식, 내 대답을 끝까지 들어주는지 같은 작은 신호를 눈여겨보세요. 회사 소개 글이나 팀 블로그, 구성원 인터뷰가 있다면 읽어보는 것도 좋아요. 면접은 회사가 나를 보는 자리이면서 내가 회사를 보는 자리이기도 해요. 직접 확인하기 어렵다면 아는 선배나 같은 업계 사람에게 조언을 구해보세요.", "Even the same work feels very different depending on who you do it with. Notice small signals from the people you meet in interviews: their attitude, how they ask questions, whether they listen to your full answer. If there's a company introduction, team blog, or employee interviews, reading them helps too. An interview is a chance for the company to see you—and for you to see the company. If it's hard to check yourself, ask a senior you know or someone in the same industry for advice.", "同样的工作，和谁一起做，体验会大不相同。留意面试中遇到的人的态度、提问方式、是否耐心听完你的回答等小信号。如果有公司介绍、团队博客或员工访谈，也读一读。面试既是公司了解你的场合，也是你了解公司的场合。如果很难亲自确认，可以向认识的前辈或同行业的人请教。", "Cùng một công việc nhưng làm với ai sẽ cho trải nghiệm rất khác. Hãy để ý những tín hiệu nhỏ từ người bạn gặp khi phỏng vấn: thái độ, cách đặt câu hỏi, có lắng nghe bạn trả lời đến cuối không. Nếu có bài giới thiệu công ty, blog của nhóm hay phỏng vấn nhân viên, hãy đọc thử. Phỏng vấn là dịp công ty nhìn bạn, và cũng là dịp bạn nhìn công ty. Nếu khó tự kiểm tra, hãy xin lời khuyên từ anh chị khóa trên hoặc người cùng ngành.", "同じ仕事でも、誰とするかによって経験は大きく変わります。面接で会った人たちの態度、質問の仕方、自分の答えを最後まで聞いてくれるかといった小さなサインに注目しましょう。会社紹介やチームブログ、社員インタビューがあれば読んでみるのも良いです。面接は会社が自分を見る場であり、自分が会社を見る場でもあります。自分で確かめるのが難しければ、知り合いの先輩や同じ業界の人に助言を求めてみましょう。", "Pekerjaan yang sama terasa sangat berbeda tergantung dengan siapa Anda bekerja. Perhatikan sinyal kecil dari orang yang Anda temui saat wawancara: sikap mereka, cara bertanya, apakah mereka mendengarkan jawaban Anda sampai selesai. Jika ada profil perusahaan, blog tim, atau wawancara karyawan, membacanya juga membantu. Wawancara adalah kesempatan perusahaan melihat Anda—sekaligus kesempatan Anda melihat perusahaan. Jika sulit memastikan sendiri, mintalah saran dari senior yang Anda kenal atau orang di industri yang sama.") },
        { heading: t("근무 조건 확인하기", "Check the work conditions", "确认工作条件", "Kiểm tra điều kiện làm việc", "勤務条件を確認する", "Cek kondisi kerja"), text: t("연봉만큼 중요한 게 근무 형태예요. 근무 시간과 장소, 재택 가능 여부, 수습 기간, 계약 형태(정규직·계약직 등)를 미리 확인하세요. 궁금한 점은 합격 후 처우를 안내받을 때 정중하게 물어봐도 괜찮아요. 유학생이라면 그 일자리가 내 체류 자격으로 일할 수 있는 곳인지, 회사가 관련 절차를 함께 진행해본 적이 있는지도 꼭 확인하세요. 조건은 나중에 바꾸기 어려운 경우가 많으니 결정 전에 확인하는 게 좋아요.", "How you'll work matters as much as salary. Check working hours and location, whether remote work is possible, any probation period, and the contract type (permanent, fixed-term, etc.) in advance. It's fine to ask politely about anything unclear when they present the offer. If you're an international student, also make sure the job is one you can do under your residence status, and whether the company has handled the related procedures before. Conditions are often hard to change later, so it's best to confirm them before deciding.", "和薪资同样重要的是工作形式。提前确认工作时间和地点、能否远程办公、试用期、合同类型（正式员工、合同工等）。有疑问的地方，在录用后沟通待遇时礼貌地询问也完全可以。如果你是留学生，一定还要确认这份工作在你的居留资格下能否从事，以及公司是否办理过相关手续。条件往往事后很难更改，所以最好在决定前确认。", "Hình thức làm việc cũng quan trọng như lương. Hãy kiểm tra trước giờ làm và địa điểm, có làm từ xa được không, thời gian thử việc, loại hợp đồng (chính thức, có thời hạn…). Điều gì chưa rõ, bạn có thể lịch sự hỏi khi được thông báo đãi ngộ sau khi trúng tuyển. Nếu là du học sinh, hãy kiểm tra thêm công việc đó có phù hợp với tư cách lưu trú của bạn không, và công ty đã từng làm các thủ tục liên quan chưa. Điều kiện thường khó thay đổi về sau, nên tốt nhất là kiểm tra trước khi quyết định.", "年収と同じくらい大切なのが勤務形態です。勤務時間と場所、在宅勤務の可否、試用期間、契約形態(正社員・契約社員など)を事前に確認しましょう。気になる点は、合格後に処遇の案内を受けるときに丁寧に尋ねても大丈夫です。留学生なら、その仕事が自分の在留資格で働ける職場か、会社が関連手続きを一緒に進めた経験があるかも必ず確認しましょう。条件は後から変えにくいことが多いので、決める前に確認しておくのが良いです。", "Cara kerja sama pentingnya dengan gaji. Cek lebih dulu jam dan lokasi kerja, kemungkinan kerja jarak jauh, masa percobaan, dan jenis kontrak (tetap, kontrak, dll.). Hal yang belum jelas boleh ditanyakan dengan sopan saat Anda menerima penawaran. Jika Anda mahasiswa asing, pastikan juga pekerjaan itu bisa dilakukan dengan status tinggal Anda, dan apakah perusahaan pernah mengurus prosedur terkait sebelumnya. Kondisi sering sulit diubah belakangan, jadi sebaiknya dipastikan sebelum memutuskan.") },
        { heading: t("완벽한 곳은 없어요", "No place is perfect", "没有完美的地方", "Không có nơi hoàn hảo", "完璧な所はありません", "Tak ada tempat sempurna"), text: t("모든 조건이 완벽한 곳은 드물어요. 나에게 중요한 2~3가지를 정하고, 그걸 충족하면 충분히 좋은 선택이에요. 예를 들어 '배울 수 있는 사수, 관심 분야의 업무, 통근 1시간 이내'처럼 구체적으로 적어보세요. 기준이 분명하면 여러 곳 중에서 고를 때도 흔들리지 않고, 첫 직장 이후의 다음 선택도 훨씬 쉬워져요. 부족한 부분은 일하면서 채워갈 수 있다는 마음으로 고르면 부담이 줄어요.", "A place where every condition is perfect is rare. Decide on 2–3 things that matter to you; if it meets those, it's a good enough choice. Write them down concretely, for example: 'a mentor I can learn from, work in my field of interest, a commute under an hour.' With clear criteria, you won't waver when choosing between offers, and your next move after your first job gets much easier too. Choosing with the mindset that you can fill the gaps while working takes off the pressure.", "所有条件都完美的地方很少。定下对你重要的2~3点，只要满足就是足够好的选择。可以具体写下来，比如『有能学习的前辈、感兴趣领域的工作、通勤1小时以内』。标准清晰了，在几个选择之间就不会摇摆，第一份工作之后的下一步也会容易得多。抱着『不足的地方可以边工作边补』的心态去选，压力会小很多。", "Nơi mọi điều kiện đều hoàn hảo rất hiếm. Hãy chọn 2–3 điều quan trọng với bạn; đáp ứng được là lựa chọn đủ tốt. Hãy viết ra cụ thể, ví dụ: 'có người hướng dẫn để học hỏi, công việc trong lĩnh vực mình quan tâm, đi làm dưới 1 tiếng'. Khi tiêu chí rõ ràng, bạn sẽ không dao động khi chọn giữa nhiều nơi, và bước tiếp theo sau công việc đầu tiên cũng dễ hơn nhiều. Chọn với suy nghĩ rằng phần còn thiếu có thể bù đắp trong lúc làm sẽ giúp bạn bớt áp lực.", "すべての条件が完璧な所はまれです。自分に大切な2〜3つを決め、それを満たせば十分良い選択です。例えば『学べる先輩がいる、関心分野の業務、通勤1時間以内』のように具体的に書いてみましょう。基準がはっきりしていれば、複数の中から選ぶときも迷わず、初めての職場の次の選択もずっと楽になります。足りない部分は働きながら埋めていけると思って選べば、負担が軽くなります。", "Tempat yang semua kondisinya sempurna itu langka. Tentukan 2–3 hal yang penting bagi Anda; jika terpenuhi, itu pilihan yang cukup baik. Tuliskan secara konkret, misalnya: 'ada mentor untuk belajar, pekerjaan di bidang yang diminati, perjalanan kurang dari satu jam'. Dengan kriteria jelas, Anda tak akan bimbang saat memilih di antara beberapa tawaran, dan langkah berikutnya setelah pekerjaan pertama juga jauh lebih mudah. Memilih dengan pola pikir bahwa kekurangan bisa dilengkapi sambil bekerja akan mengurangi beban.") },
        { heading: t("고르기 전 체크리스트", "Checklist before deciding", "做决定前的清单", "Danh sách trước khi chọn", "選ぶ前のチェックリスト", "Daftar cek sebelum memilih"), text: t("지원하거나 결정하기 전에 이렇게 점검해보세요.\n· 주요 업무가 내 관심과 맞나요?\n· 옆에서 배울 수 있는 사람이 있나요?\n· 근무 조건과 체류 자격을 확인했나요?\n· 내가 정한 기준 2~3가지를 충족하나요?\n대부분 '네'라면 자신 있게 도전해보세요. 첫 직장은 정답을 맞히는 시험이 아니라 경험을 쌓는 출발점이에요. 결정한 뒤에는 뒤돌아보기보다 그곳에서 배울 것에 집중해보세요.", "Before applying or deciding, run through this:\n· Do the key duties match my interests?\n· Is there someone I can learn from?\n· Have I checked the work conditions and my residence status?\n· Does it meet my 2–3 criteria?\nIf most answers are 'yes,' go for it with confidence. Your first job isn't a test with one right answer—it's a starting point for building experience. Once you've decided, focus on what you can learn there rather than looking back.", "投递或做决定前，这样检查一下：\n· 主要工作和我的兴趣相符吗？\n· 身边有能学习的人吗？\n· 工作条件和居留资格确认过了吗？\n· 满足我定下的2~3个标准吗？\n如果大部分是『是』，就有信心地去挑战吧。第一份工作不是只有一个正确答案的考试，而是积累经验的起点。做出决定后，与其回头看，不如专注于在那里能学到的东西。", "Trước khi ứng tuyển hay quyết định, hãy kiểm tra:\n· Nhiệm vụ chính có hợp với sở thích của mình không?\n· Có người để mình học hỏi không?\n· Đã kiểm tra điều kiện làm việc và tư cách lưu trú chưa?\n· Có đáp ứng 2–3 tiêu chí mình đặt ra không?\nNếu phần lớn là 'có', hãy tự tin thử sức. Công việc đầu tiên không phải bài thi có một đáp án đúng, mà là điểm khởi đầu để tích lũy kinh nghiệm. Sau khi đã quyết định, hãy tập trung vào những gì có thể học ở đó thay vì nhìn lại.", "応募や決定の前に、こう点検してみましょう。\n・主な業務は自分の関心と合っていますか?\n・そばで学べる人はいますか?\n・勤務条件と在留資格を確認しましたか?\n・自分で決めた基準2〜3つを満たしていますか?\nほとんど『はい』なら、自信を持って挑戦しましょう。初めての職場は正解を当てる試験ではなく、経験を積む出発点です。決めた後は振り返るより、そこで学べることに集中しましょう。", "Sebelum melamar atau memutuskan, periksa hal ini:\n· Apakah tugas utamanya sesuai minat saya?\n· Adakah orang yang bisa saya pelajari?\n· Sudahkah saya cek kondisi kerja dan status tinggal?\n· Apakah memenuhi 2–3 kriteria saya?\nJika sebagian besar jawabannya 'ya', majulah dengan percaya diri. Pekerjaan pertama bukan ujian dengan satu jawaban benar—melainkan titik awal untuk menumpuk pengalaman. Setelah memutuskan, fokuslah pada apa yang bisa dipelajari di sana alih-alih menoleh ke belakang.") }
      ]
    },
    {
      slug: "no-experience-appeal",
      emoji: "🌱",
      title: t("경력이 없는데\n어떻게 어필하죠?", "No experience—\nhow do I stand out?", "没有经验\n怎么展示自己？", "Chưa có kinh nghiệm—\nlàm sao gây ấn tượng?", "経歴がないのに\nどうアピールする？", "Tanpa pengalaman—\nbagaimana menonjol?"),
      desc: t("경험은 이미 충분히 있어요", "You already have plenty of experience", "你其实已经有足够的经验", "Bạn đã có đủ kinh nghiệm rồi", "経験はもう十分にあります", "Anda sudah punya cukup pengalaman"),
      href: "/talent/career/resume/editor",
      ctaLabel: t("이력서에 정리하기", "Organize it into a resume", "整理进简历", "Sắp xếp vào CV", "履歴書に整理する", "Rapikan ke dalam resume"),
      body: [
        { heading: t("경험의 정의를 넓혀요", "Broaden what counts as experience", "拓宽经验的定义", "Mở rộng định nghĩa kinh nghiệm", "経験の定義を広げる", "Perluas makna pengalaman"), text: t("알바·동아리·팀플·공모전·개인 프로젝트 모두 훌륭한 재료예요. '무경력'이 아니라 '아직 정리 안 된 경험'일 뿐이에요. 수업 과제, 봉사활동, 언어 교환 모임 운영처럼 사소해 보이는 일도 직무와 연결되면 충분히 어필이 돼요. 먼저 지난 몇 년간 한 일을 크고 작은 것 가리지 않고 모두 적어보는 것부터 시작해보세요. 적다 보면 잊고 있던 경험이 생각보다 많다는 걸 알게 될 거예요.", "Part-time jobs, clubs, team projects, contests, and personal projects are all great material. You're not 'inexperienced'—it's just 'experience not yet organized.' Even things that seem minor, like class assignments, volunteering, or running a language-exchange meetup, can make a strong case once connected to the role. Start by writing down everything you've done in the past few years, big or small. As you write, you'll find you have more forgotten experiences than you thought.", "兼职、社团、团队项目、比赛、个人项目都是很好的素材。你不是『没经验』，只是『还没整理的经验』。课程作业、志愿活动、组织语言交换聚会这类看似不起眼的事，只要和职位联系起来，也足以成为亮点。先从把过去几年做过的事，不论大小全部写下来开始吧。写着写着，你会发现被遗忘的经历比想象中多。", "Việc làm thêm, câu lạc bộ, dự án nhóm, cuộc thi, dự án cá nhân đều là chất liệu tuyệt vời. Bạn không 'thiếu kinh nghiệm'—chỉ là 'kinh nghiệm chưa được sắp xếp'. Cả những việc tưởng nhỏ như bài tập trên lớp, hoạt động tình nguyện, tổ chức nhóm trao đổi ngôn ngữ cũng có sức thuyết phục khi gắn với vị trí ứng tuyển. Hãy bắt đầu bằng việc ghi ra tất cả những gì bạn đã làm trong vài năm qua, dù lớn hay nhỏ. Viết ra rồi bạn sẽ thấy mình có nhiều kinh nghiệm bị lãng quên hơn bạn nghĩ.", "アルバイト・サークル・チームプロジェクト・コンテスト・個人プロジェクトすべて立派な材料です。『無経験』ではなく『まだ整理されていない経験』なだけです。授業の課題、ボランティア、言語交換の集まりの運営など些細に見えることも、職務と結びつければ十分アピールになります。まずはここ数年でしたことを、大小問わずすべて書き出すことから始めましょう。書いているうちに、忘れていた経験が思ったより多いことに気づくはずです。", "Kerja paruh waktu, klub, proyek tim, lomba, dan proyek pribadi semua materi bagus. Anda bukan 'tanpa pengalaman'—hanya 'pengalaman yang belum dirapikan'. Hal yang tampak sepele, seperti tugas kuliah, kegiatan sukarela, atau mengelola kelompok pertukaran bahasa, bisa jadi nilai jual begitu dikaitkan dengan posisi. Mulailah dengan menuliskan semua yang Anda lakukan beberapa tahun terakhir, besar maupun kecil. Saat menulis, Anda akan sadar ada lebih banyak pengalaman terlupakan dari yang Anda kira.") },
        { heading: t("결과까지 적어요", "Write down to the result", "写到结果为止", "Ghi đến cả kết quả", "結果まで書く", "Tulis sampai hasilnya"), text: t("'무엇을 했다'에서 멈추지 말고 '그래서 어떻게 됐다'까지 적어요. '주문 누락 30% 감소'처럼 변화를 보여주면 좋아요. 정확한 숫자가 없다면 '같은 문의가 눈에 띄게 줄었다', '팀 발표에서 1등을 했다'처럼 확인할 수 있는 변화를 쓰면 돼요. 부풀리기보다 직접 설명할 수 있는 사실을 적는 게 면접에서도 훨씬 안전해요. 결과를 쓸 때는 나 혼자 한 일과 팀이 함께 한 일을 구분해서 적어주세요.", "Don't stop at 'what you did'—go to 'what came of it.' Show the change, like 'cut order errors by 30%.' If you don't have exact numbers, write a change you can back up, like 'repeat questions dropped noticeably' or 'our team won first place in the presentation.' Writing facts you can explain yourself, rather than exaggerating, is much safer in interviews too. When writing results, separate what you did on your own from what the team did together.", "别停在『做了什么』，写到『结果如何』。像『订单遗漏减少30%』一样展示变化。没有准确数字的话，写下能被确认的变化也可以，比如『同样的咨询明显减少了』『在团队发表中拿了第一』。比起夸大，写自己能解释清楚的事实，在面试中也安全得多。写结果时，请把自己独立完成的和团队一起完成的区分开来。", "Đừng dừng ở 'đã làm gì'—hãy viết đến 'kết quả ra sao'. Cho thấy thay đổi như 'giảm 30% đơn bị sót'. Nếu không có số liệu chính xác, hãy viết thay đổi có thể kiểm chứng như 'các câu hỏi lặp lại giảm rõ rệt' hay 'nhóm đạt giải nhất phần thuyết trình'. Viết sự thật mà bạn tự giải thích được, thay vì phóng đại, cũng an toàn hơn nhiều khi phỏng vấn. Khi viết kết quả, hãy tách rõ việc bạn tự làm và việc cả nhóm cùng làm.", "『何をした』で止めず『それでどうなった』まで書きましょう。『注文漏れ30%削減』のように変化を見せると良いです。正確な数字がなければ『同じ問い合わせが目に見えて減った』『チーム発表で1位になった』のように確認できる変化を書けば大丈夫です。誇張するより自分で説明できる事実を書く方が、面接でもずっと安全です。結果を書くときは、自分一人でしたことと、チームで一緒にしたことを分けて書きましょう。", "Jangan berhenti di 'apa yang dilakukan'—lanjut ke 'hasilnya apa'. Tunjukkan perubahan seperti 'kesalahan pesanan turun 30%'. Jika tidak punya angka pasti, tulis perubahan yang bisa dibuktikan, seperti 'pertanyaan berulang berkurang jelas' atau 'tim kami juara satu presentasi'. Menulis fakta yang bisa Anda jelaskan sendiri, alih-alih melebih-lebihkan, juga jauh lebih aman saat wawancara. Saat menulis hasil, pisahkan apa yang Anda kerjakan sendiri dan apa yang dikerjakan tim bersama.") },
        { heading: t("직무와 연결해요", "Connect it to the role", "与职位连接", "Kết nối với vị trí", "職務と結びつける", "Hubungkan dengan posisi"), text: t("같은 경험도 지원 직무에 맞춰 강조점을 바꿔요. 카페 알바라면 영업·서비스 직무에는 고객 응대 경험으로, 운영 직무에는 재고 관리와 업무 개선 경험으로 쓸 수 있어요. 공고의 자격요건을 옆에 두고 각 항목에 맞는 내 경험을 하나씩 짝지어보면, 무엇을 강조해야 할지 금방 보여요. 공고마다 강조점을 조금씩 바꾸는 수고가 합격 가능성을 높여줘요.", "Shift the emphasis of the same experience to fit the role. A café part-time job can become customer-service experience for a sales or service role, or inventory management and process-improvement experience for an operations role. Put the posting's requirements side by side and match each item with one of your experiences—you'll quickly see what to emphasize. The effort of adjusting your emphasis for each posting improves your chances.", "同样的经验也按应聘职位调整侧重点。咖啡店兼职，投销售、服务岗位时可以写成客户接待经验，投运营岗位时可以写成库存管理和流程改进经验。把招聘的任职要求放在旁边，逐条配上自己的经验，很快就能看出该强调什么。针对每个招聘稍微调整侧重点，这份用心会提高通过的可能性。", "Chuyển điểm nhấn của cùng kinh nghiệm cho hợp vị trí. Làm thêm ở quán cà phê có thể thành kinh nghiệm phục vụ khách cho vị trí kinh doanh, dịch vụ, hoặc kinh nghiệm quản lý kho và cải tiến công việc cho vị trí vận hành. Đặt yêu cầu của tin tuyển dụng bên cạnh rồi ghép từng mục với một kinh nghiệm của bạn—bạn sẽ nhanh chóng thấy cần nhấn mạnh điều gì. Công sức điều chỉnh điểm nhấn cho từng tin tuyển dụng sẽ giúp tăng khả năng trúng tuyển.", "同じ経験でも応募職種に合わせて強調点を変えます。カフェのアルバイトなら、営業・サービス職には接客経験として、運営職には在庫管理や業務改善の経験として書けます。求人の応募資格を横に置き、各項目に合う自分の経験を一つずつ組み合わせてみると、何を強調すべきかすぐに見えてきます。求人ごとに強調点を少しずつ変える手間が、合格の可能性を高めてくれます。", "Geser penekanan pengalaman yang sama agar sesuai posisi. Kerja paruh waktu di kafe bisa menjadi pengalaman melayani pelanggan untuk posisi sales atau layanan, atau pengalaman manajemen stok dan perbaikan proses untuk posisi operasional. Taruh persyaratan lowongan di samping, lalu pasangkan tiap poin dengan satu pengalaman Anda—Anda akan cepat melihat apa yang perlu ditonjolkan. Usaha menyesuaikan penekanan untuk tiap lowongan akan meningkatkan peluang Anda.") },
        { heading: t("이렇게 바꿔 써요", "Rewrite it like this", "这样改写", "Viết lại như thế này", "こう書き換える", "Tulis ulang seperti ini"), text: t("예시로 비교해볼게요.\n· 전: 편의점에서 1년간 아르바이트를 했습니다.\n· 후: 야간 근무 중 재고 확인표를 만들어 발주 실수를 줄였고, 신규 근무자 교육을 맡았습니다.\n같은 경험이지만 뒤의 문장은 '스스로 문제를 찾고 개선한 사람'으로 읽혀요. 내 경험도 '행동 + 결과'가 보이게 다시 써보세요. 숫자가 없어도 행동이 구체적이면 충분히 설득력이 생겨요.", "Here's a comparison:\n· Before: I worked part-time at a convenience store for a year.\n· After: On night shifts, I made a stock checklist that reduced ordering mistakes, and I was put in charge of training new staff.\nIt's the same experience, but the second reads as 'someone who finds problems and fixes them.' Rewrite your own experiences so the action and result are visible. Even without numbers, specific actions are convincing enough.", "举个例子对比一下：\n· 改前：在便利店做了一年兼职。\n· 改后：夜班时制作了库存核对表，减少了订货失误，还负责培训新员工。\n同样的经历，后一句读起来就是『会自己发现问题并改进的人』。把你的经历也改写成能看到『行动+结果』的样子吧。即使没有数字，只要行动具体，就足够有说服力。", "Hãy so sánh qua ví dụ:\n· Trước: Tôi đã làm thêm ở cửa hàng tiện lợi một năm.\n· Sau: Khi làm ca đêm, tôi lập bảng kiểm kho giúp giảm sai sót khi đặt hàng, và được giao đào tạo nhân viên mới.\nCùng một kinh nghiệm, nhưng câu sau cho thấy bạn là 'người tự tìm ra vấn đề và cải thiện'. Hãy viết lại kinh nghiệm của bạn sao cho thấy rõ 'hành động + kết quả'. Dù không có con số, hành động cụ thể cũng đủ thuyết phục.", "例で比べてみましょう。\n・前:コンビニで1年間アルバイトをしました。\n・後:夜勤中に在庫確認表を作って発注ミスを減らし、新人スタッフの教育を任されました。\n同じ経験でも、後の文は『自分で問題を見つけて改善する人』と読めます。自分の経験も『行動+結果』が見えるように書き直してみましょう。数字がなくても、行動が具体的なら十分説得力が生まれます。", "Mari bandingkan lewat contoh:\n· Sebelum: Saya bekerja paruh waktu di minimarket selama setahun.\n· Sesudah: Saat sif malam, saya membuat daftar cek stok yang mengurangi kesalahan pemesanan, dan dipercaya melatih staf baru.\nPengalamannya sama, tetapi kalimat kedua terbaca sebagai 'orang yang menemukan masalah dan memperbaikinya'. Tulis ulang pengalaman Anda agar 'tindakan + hasil' terlihat. Meski tanpa angka, tindakan yang spesifik sudah cukup meyakinkan.") },
        { heading: t("유학생의 강점", "Strengths of int'l students", "留学生的优势", "Thế mạnh của du học sinh", "留学生の強み", "Kekuatan mahasiswa asing"), text: t("한국에서 유학하며 낯선 환경에 적응한 경험 자체가 좋은 이야기예요. 새 언어를 배운 과정, 다른 문화의 친구들과 팀 과제를 한 경험, 모국어 통역을 도운 일은 적응력·소통력·책임감을 보여줘요. 이런 경험을 '무엇이 어려웠고, 어떻게 해결했는지' 순서로 정리하면 어떤 직무에서도 설득력 있게 쓸 수 있어요. 한국어로 이런 이야기를 미리 써보고 소리 내어 읽어보면 면접 준비도 함께 돼요.", "Adapting to an unfamiliar environment while studying in Korea is a great story in itself. Learning a new language, doing team projects with friends from other cultures, or helping interpret in your native language all show adaptability, communication, and responsibility. Organize these in the order 'what was hard, and how you solved it,' and they'll be convincing for almost any role. Writing these stories in Korean ahead of time and reading them aloud doubles as interview prep.", "在韩国留学、适应陌生环境的经历本身就是很好的故事。学习新语言的过程、和不同文化背景的同学做团队作业、帮忙做母语翻译，都能体现适应力、沟通力和责任感。按『遇到了什么困难、是怎么解决的』的顺序整理这些经历，无论哪个职位都能写得很有说服力。提前用韩语把这些故事写下来并出声读一读，也就顺便准备了面试。", "Bản thân trải nghiệm thích nghi với môi trường lạ khi du học ở Hàn đã là một câu chuyện hay. Quá trình học ngôn ngữ mới, làm bài tập nhóm với bạn bè khác văn hóa, hay giúp phiên dịch tiếng mẹ đẻ đều cho thấy khả năng thích nghi, giao tiếp và tinh thần trách nhiệm. Sắp xếp những trải nghiệm này theo thứ tự 'điều gì khó khăn và bạn đã giải quyết thế nào' thì vị trí nào cũng có thể viết thuyết phục. Viết trước những câu chuyện này bằng tiếng Hàn và đọc to lên cũng là cách chuẩn bị phỏng vấn.", "韓国に留学して慣れない環境に適応した経験そのものが良いストーリーです。新しい言語を学んだ過程、異なる文化の友人とチーム課題をした経験、母国語の通訳を手伝ったことは、適応力・コミュニケーション力・責任感を示します。こうした経験を『何が難しく、どう解決したか』の順に整理すれば、どんな職務でも説得力を持って書けます。こうした話を韓国語で先に書き、声に出して読んでみると、面接の準備にもなります。", "Pengalaman beradaptasi di lingkungan asing selama kuliah di Korea sudah merupakan cerita yang bagus. Proses belajar bahasa baru, mengerjakan tugas tim dengan teman dari budaya lain, atau membantu menerjemahkan bahasa ibu menunjukkan kemampuan beradaptasi, komunikasi, dan tanggung jawab. Susun pengalaman ini dengan urutan 'apa yang sulit dan bagaimana Anda mengatasinya', maka akan meyakinkan untuk hampir semua posisi. Menulis cerita ini dalam bahasa Korea lebih dulu dan membacanya keras-keras sekaligus menjadi persiapan wawancara.") },
        { heading: t("지금 해볼 일", "What to do now", "现在就做", "Việc làm ngay", "今やってみること", "Lakukan sekarang"), text: t("오늘 바로 해볼 수 있는 것부터 시작해요.\n· 지난 경험을 모두 목록으로 적기\n· 각 경험에 '그래서 어떻게 됐나'를 한 줄씩 붙이기\n· 지원할 공고 하나를 골라 맞는 경험 3개 고르기\n이 세 단계만 해도 이력서의 빈칸이 생각보다 빨리 채워져요. 정리한 내용은 이력서 편집기에 바로 옮겨보세요. 한 번에 완벽하게 쓰려 하지 말고, 조금씩 고쳐가면 돼요.", "Start with what you can do today:\n· List all your past experiences\n· Add one line to each: 'so what happened?'\n· Pick one posting and choose 3 experiences that fit\nJust these three steps fill the blanks in your resume faster than you'd think. Move what you've organized straight into the resume editor. Don't try to write it perfectly in one go—just keep refining it bit by bit.", "从今天就能做的事开始：\n· 把过去的经历全部列出来\n· 每条经历后面补一句『结果怎么样』\n· 选一个想投的招聘，挑出3个对应的经历\n光是这三步，简历的空白就会比想象中更快被填满。把整理好的内容直接放进简历编辑器吧。不必一次写得完美，一点点修改就好。", "Bắt đầu từ việc có thể làm ngay hôm nay:\n· Liệt kê tất cả kinh nghiệm đã qua\n· Thêm một dòng 'kết quả ra sao' cho mỗi kinh nghiệm\n· Chọn một tin tuyển dụng và chọn 3 kinh nghiệm phù hợp\nChỉ ba bước này thôi, chỗ trống trong CV sẽ được lấp nhanh hơn bạn nghĩ. Hãy chuyển ngay nội dung đã sắp xếp vào trình chỉnh sửa CV. Đừng cố viết hoàn hảo ngay một lần—cứ sửa dần từng chút là được.", "今日すぐできることから始めましょう。\n・これまでの経験をすべてリストにする\n・各経験に『それでどうなった』を一行ずつ添える\n・応募したい求人を一つ選び、合う経験を3つ選ぶ\nこの3ステップだけでも、履歴書の空欄が思ったより早く埋まります。整理した内容は履歴書エディターにすぐ移してみましょう。一度で完璧に書こうとせず、少しずつ直していけば大丈夫です。", "Mulailah dari yang bisa dilakukan hari ini:\n· Daftar semua pengalaman Anda\n· Tambahkan satu baris 'lalu hasilnya apa' di tiap pengalaman\n· Pilih satu lowongan dan pilih 3 pengalaman yang cocok\nTiga langkah ini saja sudah mengisi bagian kosong resume lebih cepat dari dugaan. Pindahkan hasilnya langsung ke editor resume. Jangan berusaha menulis sempurna sekaligus—cukup perbaiki sedikit demi sedikit.") }
      ]
    },
    {
      slug: "is-internship-needed",
      emoji: "🤝",
      title: t("인턴, 꼭\n해야 할까요?", "Do I really\nneed an internship?", "实习\n一定要做吗？", "Có nhất thiết\nphải thực tập?", "インターンは\n必ずすべき？", "Apakah magang\nitu wajib?"),
      desc: t("인턴을 200% 활용하는 법", "How to make the most of an internship", "把实习用到200%的方法", "Cách tận dụng thực tập tối đa", "インターンを200%活用する方法", "Cara memaksimalkan magang"),
      href: "/talent/jobs",
      ctaLabel: t("인턴 공고 보기", "See internship postings", "查看实习招聘", "Xem tin tuyển thực tập", "インターン求人を見る", "Lihat lowongan magang"),
      body: [
        { heading: t("가장 빠른 실무 경험", "The fastest real-work experience", "最快的实操经验", "Kinh nghiệm thực tế nhanh nhất", "最も早い実務経験", "Pengalaman kerja nyata tercepat"), text: t("인턴은 '실제로 일해본 경험'을 만드는 가장 확실한 방법이에요. 짧아도 이력서에서 큰 힘을 발휘해요. 꼭 해야 하는 건 아니지만, 회사가 실제로 어떻게 돌아가는지 직접 보고 나에게 맞는 직무인지 확인할 수 있다는 점에서 가치가 커요. 생각했던 일과 실제 일이 다르다는 걸 일찍 알게 되는 것도 중요한 수확이에요. 그래서 인턴은 결과보다 '방향을 확인하는 기회'로 생각하면 부담이 줄어요.", "An internship is the surest way to build 'experience actually working.' Even a short one carries great weight on a resume. It isn't mandatory, but it's valuable because you see firsthand how a company really runs and can check whether the role suits you. Finding out early that the real work differs from what you imagined is also an important gain. So thinking of an internship as 'a chance to check your direction' rather than a result takes off the pressure.", "实习是积累『真正工作过的经验』最确实的方法。即使短暂，也在简历上发挥很大作用。并不是非做不可，但能亲眼看到公司实际如何运转、确认这个职位是否适合自己，这一点很有价值。尽早发现想象中的工作和实际不同，也是很重要的收获。所以把实习看作『确认方向的机会』而不是结果，压力会小很多。", "Thực tập là cách chắc chắn nhất để tạo 'kinh nghiệm làm việc thực tế'. Dù ngắn cũng có sức nặng lớn trong CV. Không bắt buộc, nhưng rất giá trị vì bạn được tận mắt thấy công ty vận hành ra sao và kiểm tra vị trí đó có hợp với mình không. Sớm nhận ra công việc thực tế khác với tưởng tượng cũng là một thu hoạch quan trọng. Vì vậy, hãy xem thực tập là 'cơ hội kiểm tra định hướng' thay vì kết quả để bớt áp lực.", "インターンは『実際に働いた経験』を作る最も確実な方法です。短くても履歴書で大きな力を発揮します。必須ではありませんが、会社が実際にどう回っているかを直接見て、自分に合う職務か確かめられる点で価値が大きいです。思っていた仕事と実際の仕事が違うと早めに知ることも、大切な収穫です。だからインターンは結果より『方向を確かめる機会』と考えると、負担が軽くなります。", "Magang adalah cara paling pasti membangun 'pengalaman benar-benar bekerja'. Meski singkat, sangat berbobot di resume. Tidak wajib, tetapi bernilai besar karena Anda melihat langsung bagaimana perusahaan berjalan dan bisa memastikan apakah posisi itu cocok. Mengetahui lebih awal bahwa pekerjaan nyata berbeda dari bayangan juga merupakan hasil yang penting. Jadi, anggaplah magang sebagai 'kesempatan memastikan arah', bukan hasil, agar bebannya berkurang.") },
        { heading: t("인턴이 어렵다면", "If internships are hard to get", "如果很难找到实习", "Nếu khó tìm thực tập", "インターンが難しいなら", "Jika sulit dapat magang"), text: t("인턴 기회를 바로 얻기 어려워도 괜찮아요. 기업 연계 프로젝트, 공모전, 학교의 현장실습, 단기 프리랜스 작업, 직무 관련 동아리도 실무에 가까운 경험을 쌓는 방법이에요. 중요한 건 이름보다 '실제 문제를 다른 사람과 함께 풀어본 경험'이에요. 이런 경험도 결과까지 정리하면 인턴 못지않은 재료가 돼요. 작은 경험이라도 꾸준히 쌓으면 인턴 지원서를 쓸 때 든든한 근거가 돼요.", "It's okay if you can't land an internship right away. Company-linked projects, contests, school field placements, short freelance gigs, and role-related clubs are also ways to build near-real-work experience. What matters isn't the label but 'experience solving real problems with other people.' Organized down to the results, these can be just as strong as an internship. Even small experiences, built up steadily, become solid evidence when you write internship applications.", "一时拿不到实习机会也没关系。企业合作项目、比赛、学校的现场实习、短期自由职业、与职位相关的社团，也都是积累接近实务经验的方式。重要的不是名称，而是『和别人一起解决过真实问题的经验』。把这些经验也整理到结果，就是不输实习的素材。哪怕是小经历，持续积累下来，写实习申请时也会成为有力的依据。", "Chưa có ngay cơ hội thực tập cũng không sao. Dự án liên kết doanh nghiệp, cuộc thi, thực tập thực tế của trường, công việc freelance ngắn hạn, câu lạc bộ liên quan đến nghề cũng là cách tích lũy kinh nghiệm gần với thực tế. Điều quan trọng không phải tên gọi mà là 'kinh nghiệm cùng người khác giải quyết vấn đề thật'. Sắp xếp đến tận kết quả, những kinh nghiệm này cũng có giá trị không kém thực tập. Dù là kinh nghiệm nhỏ, tích lũy đều đặn sẽ thành căn cứ vững chắc khi viết đơn xin thực tập.", "インターンの機会がすぐ得られなくても大丈夫です。企業連携プロジェクト、コンテスト、学校の現場実習、短期のフリーランス、職務関連のサークルも、実務に近い経験を積む方法です。大切なのは名前より『実際の問題を他の人と一緒に解いた経験』です。こうした経験も結果まで整理すれば、インターンに劣らない材料になります。小さな経験でもコツコツ積めば、インターンの応募書類を書くときの心強い根拠になります。", "Tidak apa-apa jika belum langsung dapat magang. Proyek kerja sama perusahaan, lomba, praktik lapangan kampus, pekerjaan lepas jangka pendek, dan klub terkait bidang kerja juga cara membangun pengalaman yang mendekati dunia kerja. Yang penting bukan labelnya, melainkan 'pengalaman memecahkan masalah nyata bersama orang lain'. Jika dirapikan sampai hasilnya, pengalaman ini sama kuatnya dengan magang. Pengalaman kecil pun, jika dikumpulkan terus, menjadi bukti kuat saat menulis lamaran magang.") },
        { heading: t("인턴 고르는 법", "How to choose an internship", "怎么选实习", "Cách chọn nơi thực tập", "インターンの選び方", "Cara memilih magang"), text: t("인턴 공고를 볼 때는 회사 이름보다 '어떤 일을 맡게 되는지'를 먼저 확인하세요. 단순 반복 업무만 하는지, 실제 프로젝트에 참여할 기회가 있는지에 따라 얻는 경험이 크게 달라요. 기간과 근무 시간, 학업과 병행할 수 있는지도 따져보세요. 유학생이라면 인턴 근무가 내 체류 자격으로 가능한지 학교나 관련 기관에 미리 확인하는 게 안전해요. 면접에서 '인턴 기간에 주로 어떤 일을 하게 되나요?'라고 직접 물어보는 것도 좋은 방법이에요.", "When you look at internship postings, check 'what you'll actually be doing' before the company name. Whether it's only repetitive tasks or there's a chance to join real projects makes a big difference in what you gain. Also consider the length, working hours, and whether you can balance it with your studies. If you're an international student, it's safest to check with your school or the relevant office in advance whether you can intern under your residence status. Asking directly in the interview, 'What will I mainly do during the internship?' is also a good idea.", "看实习招聘时，先确认『会负责什么工作』，再看公司名。只做简单重复的工作，还是有机会参与真正的项目，收获会差很多。也要考虑实习时长、工作时间、能否兼顾学业。如果你是留学生，最好提前向学校或相关机构确认，以你的居留资格能否实习。在面试中直接问『实习期间主要会做哪些工作？』也是个好方法。", "Khi xem tin tuyển thực tập, hãy xem 'bạn sẽ được giao việc gì' trước tên công ty. Chỉ làm việc lặp lại đơn giản hay có cơ hội tham gia dự án thật sẽ khiến kinh nghiệm thu được khác nhau rất nhiều. Hãy cân nhắc cả thời gian thực tập, giờ làm và khả năng kết hợp với việc học. Nếu là du học sinh, tốt nhất hãy hỏi trước trường hoặc cơ quan liên quan xem tư cách lưu trú của bạn có cho phép thực tập không. Hỏi thẳng trong buổi phỏng vấn 'Trong thời gian thực tập tôi chủ yếu làm gì?' cũng là cách hay.", "インターン求人を見るときは、会社名より『どんな仕事を任されるか』を先に確認しましょう。単純な繰り返し業務だけなのか、実際のプロジェクトに参加する機会があるのかで、得られる経験は大きく変わります。期間や勤務時間、学業と両立できるかも考えましょう。留学生なら、インターン勤務が自分の在留資格で可能か、学校や関連機関に事前に確認するのが安全です。面接で『インターン期間中は主にどんな仕事をしますか?』と直接聞いてみるのも良い方法です。", "Saat melihat lowongan magang, cek dulu 'apa yang akan Anda kerjakan' sebelum nama perusahaannya. Apakah hanya tugas berulang atau ada kesempatan ikut proyek nyata sangat menentukan pengalaman yang didapat. Pertimbangkan juga durasi, jam kerja, dan apakah bisa diimbangi dengan kuliah. Jika Anda mahasiswa asing, paling aman tanyakan dulu ke kampus atau instansi terkait apakah status tinggal Anda memungkinkan untuk magang. Bertanya langsung saat wawancara, 'Apa yang terutama akan saya kerjakan selama magang?', juga cara yang bagus.") },
        { heading: t("배운 걸 기록해요", "Record what you learn", "记录学到的东西", "Ghi lại điều học được", "学んだことを記録する", "Catat yang dipelajari"), text: t("인턴 중 한 일, 배운 것, 만든 결과를 그때그때 남겨두세요. 나중에 이력서·면접에서 그대로 재료가 돼요. 매주 금요일에 '이번 주에 한 일 3가지, 배운 점 1가지'를 메모하는 식으로 습관을 만들면 좋아요. 끝나고 나면 기억이 금방 흐려지니 숫자와 결과도 함께 적되, 회사 내부 자료는 개인적으로 가져가지 않도록 주의하세요. 이렇게 쌓인 기록은 회고를 쓰거나 다음 목표를 정할 때도 큰 도움이 돼요.", "Note what you did, learned, and produced during the internship as you go. It becomes ready-made material for your resume and interviews later. A good habit is jotting down 'three things I did and one thing I learned this week' every Friday. Memories fade quickly once it's over, so record numbers and results too—but be careful not to take internal company materials for personal use. These records also help a lot when you write a retrospective or set your next goal.", "把实习期间做的事、学到的、做出的成果随时记下来。以后在简历、面试里可以直接当素材。可以养成每周五记下『本周做的3件事、学到的1点』的习惯。实习结束后记忆很快会模糊，所以把数字和结果也一并记下，但要注意不要私自带走公司内部资料。这样积累的记录，在写复盘或制定下一个目标时也很有帮助。", "Ghi lại việc đã làm, điều học được và kết quả tạo ra ngay trong lúc thực tập. Về sau sẽ thành chất liệu sẵn cho CV và phỏng vấn. Một thói quen tốt là mỗi thứ Sáu ghi lại '3 việc đã làm và 1 điều học được trong tuần'. Kết thúc rồi thì ký ức phai nhanh, nên hãy ghi cả số liệu và kết quả—nhưng chú ý không mang tài liệu nội bộ của công ty về dùng riêng. Những ghi chép này cũng rất hữu ích khi bạn viết tổng kết hoặc đặt mục tiêu tiếp theo.", "インターン中にした仕事、学んだこと、作った成果をその都度残しておきましょう。後で履歴書・面接でそのまま材料になります。毎週金曜日に『今週やったこと3つ、学んだこと1つ』をメモする習慣をつけると良いです。終わると記憶はすぐ薄れるので数字や結果も一緒に書きつつ、社内資料は個人的に持ち出さないよう注意しましょう。こうして積み重ねた記録は、振り返りを書いたり次の目標を決めたりするときにも役立ちます。", "Catat apa yang dilakukan, dipelajari, dan dihasilkan selama magang seketika itu. Nanti jadi materi siap pakai untuk resume dan wawancara. Kebiasaan yang baik adalah mencatat '3 hal yang dikerjakan dan 1 pelajaran minggu ini' setiap Jumat. Ingatan cepat memudar setelah selesai, jadi catat juga angka dan hasilnya—tapi hati-hati agar tidak membawa dokumen internal perusahaan untuk keperluan pribadi. Catatan yang terkumpul ini juga sangat membantu saat menulis refleksi atau menentukan target berikutnya.") },
        { heading: t("인턴 기간 보내는 법", "Making the most of it", "实习期间怎么过", "Tận dụng thời gian thực tập", "インターン期間の過ごし方", "Memaksimalkan masa magang"), text: t("처음 몇 주는 모르는 게 당연해요. 질문은 모아서 정리한 뒤 물어보고, 받은 피드백은 다음 작업에 바로 반영해보세요. 맡은 일이 작아도 기한을 지키고 진행 상황을 먼저 공유하면 신뢰가 쌓여요. 점심시간이나 짧은 대화 때 선배들이 어떤 길을 거쳐 지금의 일을 하게 됐는지 물어보는 것도 큰 공부가 돼요. 모르는 걸 숨기기보다 배우려는 자세를 보여주는 게 인턴에게 가장 기대되는 모습이에요.", "Not knowing things in the first few weeks is natural. Collect your questions and ask them together, and apply feedback to your next task right away. Even if your tasks are small, meeting deadlines and sharing progress proactively builds trust. Asking colleagues over lunch or a quick chat how they got to their current role is also a great way to learn. Rather than hiding what you don't know, showing eagerness to learn is what's most expected of an intern.", "最初几周不懂是理所当然的。把问题攒起来整理好再问，收到的反馈马上用到下一项工作中。哪怕负责的事情很小，按时完成并主动汇报进度，就能积累信任。午饭或闲聊时问问前辈们是怎样走到现在这份工作的，也是很好的学习。与其掩饰不懂的地方，不如展现愿意学习的态度，这才是对实习生最大的期待。", "Vài tuần đầu chưa biết gì là chuyện bình thường. Hãy gom câu hỏi lại, sắp xếp rồi mới hỏi, và áp dụng ngay phản hồi nhận được vào việc tiếp theo. Dù việc được giao nhỏ, đúng hạn và chủ động chia sẻ tiến độ sẽ tạo dựng lòng tin. Hỏi các anh chị trong giờ ăn trưa hay lúc trò chuyện ngắn xem họ đã đi con đường nào để làm công việc hiện tại cũng là bài học lớn. Thay vì giấu điều chưa biết, thể hiện tinh thần học hỏi mới là điều người ta mong đợi nhất ở thực tập sinh.", "最初の数週間は分からないのが当たり前です。質問はまとめて整理してから聞き、もらったフィードバックは次の作業にすぐ反映しましょう。任された仕事が小さくても、期限を守り進捗を先に共有すれば信頼が積み重なります。昼休みやちょっとした会話で、先輩がどんな道を経て今の仕事に就いたかを聞くのも大きな勉強になります。分からないことを隠すより、学ぼうとする姿勢を見せることが、インターンに最も期待される姿です。", "Tidak tahu banyak hal di minggu-minggu awal itu wajar. Kumpulkan pertanyaan, rapikan, lalu tanyakan sekaligus, dan terapkan umpan balik langsung di tugas berikutnya. Meski tugasnya kecil, menepati tenggat dan aktif membagikan perkembangan akan membangun kepercayaan. Bertanya pada senior saat makan siang atau obrolan singkat tentang jalan yang mereka tempuh hingga pekerjaan sekarang juga pelajaran berharga. Daripada menyembunyikan yang belum diketahui, menunjukkan semangat belajar adalah hal yang paling diharapkan dari peserta magang.") },
        { heading: t("전환도 노려봐요", "Aim for conversion too", "也争取转正", "Cũng nhắm đến chuyển chính thức", "転換も狙ってみる", "Incar juga pengangkatan"), text: t("성실함과 태도를 보이면 정규직 전환·추천으로 이어지기도 해요. 인턴을 '긴 면접'이라 생각하고 임해요. 인턴이 끝날 무렵에는 함께 일한 분들께 감사 인사를 전하고, 가능하면 피드백이나 추천을 부탁해보세요. 전환이 되지 않더라도 그때 쌓은 경험과 인연이 다음 지원에서 든든한 힘이 돼요. 끝난 뒤에도 가끔 근황을 전하며 인연을 이어가 보세요.", "Showing diligence and a good attitude can lead to a full-time offer or a referral. Approach the internship as a 'long interview.' As it wraps up, thank the people you worked with and, if possible, ask for feedback or a recommendation. Even if it doesn't turn into a job, the experience and connections you built will be a strong asset in your next application. After it ends, keep the connection going by sharing updates now and then.", "展现踏实和态度，有时能带来转正或推荐。把实习当作『长面试』来对待。实习快结束时，向一起工作的同事表达感谢，可以的话请他们给些反馈或推荐。即使没能转正，那段时间积累的经验和人脉，也会成为下一次求职的有力支撑。实习结束后，也不妨偶尔分享近况，把这份缘分延续下去。", "Thể hiện sự tận tâm và thái độ tốt có thể dẫn đến chuyển chính thức hoặc được giới thiệu. Hãy xem thực tập như một 'cuộc phỏng vấn dài'. Khi sắp kết thúc, hãy gửi lời cảm ơn đến những người đã làm cùng và nếu được, nhờ họ góp ý hoặc giới thiệu. Dù không được chuyển chính thức, kinh nghiệm và mối quan hệ khi đó sẽ là chỗ dựa vững chắc cho lần ứng tuyển sau. Sau khi kết thúc, hãy thỉnh thoảng hỏi thăm để giữ mối quan hệ.", "誠実さと態度を見せれば正社員転換・推薦につながることもあります。インターンを『長い面接』だと思って臨みましょう。終わりが近づいたら、一緒に働いた人たちに感謝を伝え、可能ならフィードバックや推薦をお願いしてみましょう。転換に至らなくても、そこで積んだ経験とご縁が次の応募で心強い力になります。終わった後も、ときどき近況を伝えてご縁をつないでいきましょう。", "Menunjukkan ketekunan dan sikap baik bisa berujung pengangkatan tetap atau rekomendasi. Anggap magang sebagai 'wawancara panjang'. Menjelang akhir, sampaikan terima kasih kepada rekan kerja dan, jika memungkinkan, mintalah umpan balik atau rekomendasi. Meski tidak diangkat, pengalaman dan relasi yang terbangun akan menjadi kekuatan besar di lamaran berikutnya. Setelah selesai, sesekali kabari perkembangan Anda untuk menjaga relasi.") }
      ]
    },
    {
      slug: "interview-preparation",
      emoji: "💬",
      title: t("면접,\n뭘 준비하죠?", "Interviews:\nwhat to prepare?", "面试\n准备什么？", "Phỏng vấn:\nchuẩn bị gì?", "面接、\n何を準備する？", "Wawancara:\nsiapkan apa?"),
      desc: t("단골 질문 3개부터 시작", "Start with the 3 regular questions", "从3个常见问题开始", "Bắt đầu từ 3 câu hỏi quen thuộc", "定番質問3つから始める", "Mulai dari 3 pertanyaan langganan"),
      href: "/talent/career/interviews",
      ctaLabel: t("면접 준비하러 가기", "Go prepare for interviews", "去准备面试", "Đi chuẩn bị phỏng vấn", "面接の準備へ", "Mulai persiapan wawancara"),
      body: [
        { heading: t("단골 질문 3개", "The 3 regular questions", "3个常见问题", "3 câu hỏi quen thuộc", "定番質問3つ", "3 pertanyaan langganan"), text: t("자기소개, 지원 동기, 강점 — 이 셋은 거의 항상 나와요. 내 경험을 예시로 붙여 답을 미리 준비하세요. 답은 1분 안팎으로, '결론 → 경험 → 회사와의 연결' 순서로 말하면 깔끔해요. 대본을 통째로 외우기보다 핵심 키워드만 정해두고 여러 번 소리 내어 말해보는 게 실제 면접에서 훨씬 자연스러워요. 녹음해서 들어보면 말이 빠른지, 군더더기가 많은지 쉽게 알 수 있어요.", "Self-intro, motivation, strengths—these three almost always come up. Prepare answers in advance by attaching your experiences as examples. Keep each answer to about a minute, in the order 'conclusion → experience → connection to the company.' Rather than memorizing a full script, set a few keywords and say it out loud several times—it sounds far more natural in the real interview. Recording and listening back makes it easy to tell if you speak too fast or ramble.", "自我介绍、求职动机、优势——这三个几乎必问。用自己的经验作例子提前准备好回答。每个回答控制在1分钟左右，按『结论→经历→与公司的关联』的顺序说会很清晰。与其整段背稿，不如定好几个关键词，多出声练几遍，真正面试时会自然得多。录下来听一听，就很容易发现自己是不是说得太快、废话太多。", "Giới thiệu bản thân, động cơ, điểm mạnh—ba câu này gần như luôn có. Chuẩn bị trước bằng cách gắn kinh nghiệm làm ví dụ. Mỗi câu trả lời khoảng 1 phút, theo thứ tự 'kết luận → kinh nghiệm → liên hệ với công ty' sẽ gọn gàng. Thay vì học thuộc cả kịch bản, hãy chọn vài từ khóa chính và nói to nhiều lần—khi phỏng vấn thật sẽ tự nhiên hơn nhiều. Ghi âm rồi nghe lại sẽ dễ nhận ra bạn nói quá nhanh hay lan man.", "自己紹介、志望動機、強み — この3つはほぼ必ず出ます。自分の経験を例として添えて答えを先に準備しましょう。答えは1分前後で、『結論→経験→会社とのつながり』の順に話すとすっきりします。台本を丸ごと暗記するより、キーワードだけ決めて何度も声に出して話してみる方が、本番でずっと自然です。録音して聞いてみると、話すのが速すぎないか、余計な言葉が多くないかがすぐ分かります。", "Perkenalan diri, motivasi, kelebihan—tiga ini hampir selalu muncul. Siapkan jawaban lebih dulu dengan menempelkan pengalaman sebagai contoh. Jaga tiap jawaban sekitar satu menit, dengan urutan 'kesimpulan → pengalaman → kaitan dengan perusahaan'. Daripada menghafal naskah utuh, tentukan beberapa kata kunci dan ucapkan berulang kali—akan terdengar jauh lebih alami saat wawancara sesungguhnya. Merekam lalu mendengarkan ulang memudahkan Anda tahu apakah bicara terlalu cepat atau bertele-tele.") },
        { heading: t("공고에서 질문을 뽑아요", "Pull questions from the posting", "从招聘启事里提炼问题", "Rút câu hỏi từ tin tuyển dụng", "求人から質問を引き出す", "Tarik pertanyaan dari lowongan"), text: t("채용 공고의 '자격요건·우대사항'을 질문으로 바꿔 연습하면 실제 면접과 거의 겹쳐요. 예를 들어 '데이터 분석 경험 우대'라고 적혀 있다면 '데이터를 활용해 결정해본 경험이 있나요?'라는 질문을 예상할 수 있어요. 회사의 서비스와 최근 소식도 살펴보고, '왜 이 회사인지'를 내 말로 설명할 수 있게 준비하세요. 지원 동기가 회사 소개 문장을 그대로 옮긴 것처럼 들리지 않게 내 경험과 꼭 연결해주세요.", "Turn the posting's 'requirements and preferred points' into questions and practice—they overlap heavily with the real interview. For example, if it says 'data analysis experience preferred,' you can expect 'Have you ever made a decision using data?' Look into the company's services and recent news too, and be ready to explain 'why this company' in your own words. Make sure to tie your motivation to your own experience so it doesn't sound copied from the company's About page.", "把招聘的『任职要求·加分项』变成问题来练习，会和实际面试几乎重合。比如写着『有数据分析经验者优先』，就可以预想到『你有过用数据做决策的经验吗？』这样的问题。也看看公司的服务和最新动态，准备好用自己的话说明『为什么选这家公司』。一定要把求职动机和自己的经历联系起来，别让它听起来像是照搬公司介绍。", "Biến 'yêu cầu và ưu tiên' trong tin tuyển dụng thành câu hỏi để luyện—gần như trùng với phỏng vấn thật. Ví dụ, nếu ghi 'ưu tiên có kinh nghiệm phân tích dữ liệu', bạn có thể đoán câu 'Bạn đã từng dùng dữ liệu để ra quyết định chưa?'. Hãy tìm hiểu cả dịch vụ và tin tức gần đây của công ty, và chuẩn bị giải thích 'vì sao chọn công ty này' bằng lời của mình. Hãy gắn động cơ ứng tuyển với trải nghiệm của bạn để nó không nghe như chép lại phần giới thiệu công ty.", "求人の『応募資格・優遇事項』を質問に変えて練習すると、実際の面接とほぼ重なります。例えば『データ分析経験者優遇』とあれば、『データを活用して決めた経験はありますか?』という質問が予想できます。会社のサービスや最近のニュースも調べ、『なぜこの会社なのか』を自分の言葉で説明できるよう準備しましょう。志望動機が会社紹介の文章をそのまま写したように聞こえないよう、必ず自分の経験と結びつけましょう。", "Ubah 'persyaratan dan nilai plus' lowongan jadi pertanyaan lalu latih—sangat mirip dengan wawancara sesungguhnya. Misalnya, jika tertulis 'diutamakan berpengalaman analisis data', Anda bisa menduga pertanyaan 'Pernahkah Anda mengambil keputusan berdasarkan data?'. Pelajari juga layanan dan berita terbaru perusahaan, dan siapkan penjelasan 'mengapa perusahaan ini' dengan kata-kata Anda sendiri. Pastikan motivasi Anda terhubung dengan pengalaman sendiri agar tidak terdengar seperti menyalin profil perusahaan.") },
        { heading: t("경험 답변은 STAR로", "Use STAR for stories", "经历类回答用STAR", "Trả lời kinh nghiệm bằng STAR", "経験の回答はSTARで", "Jawab pengalaman dengan STAR"), text: t("'어려움을 극복한 경험' 같은 질문에는 STAR 구조가 도움이 돼요.\n· 상황(S): 어떤 상황이었나\n· 과제(T): 내가 맡은 역할은 무엇이었나\n· 행동(A): 구체적으로 무엇을 했나\n· 결과(R): 어떻게 됐고 무엇을 배웠나\n특히 '행동'을 가장 길고 구체적으로 말하는 게 핵심이에요. 미리 경험 2~3개를 이 틀로 정리해두면 여러 질문에 돌려 쓸 수 있어요. 실제 있었던 일이라 꼬리 질문에도 자신 있게 답할 수 있어요.", "For questions like 'Tell me about a challenge you overcame,' the STAR structure helps:\n· Situation: what was going on\n· Task: what your role was\n· Action: what exactly you did\n· Result: what happened and what you learned\nThe key is making 'Action' the longest and most specific part. Prepare 2–3 experiences in this format and you can reuse them across many questions. Because they really happened, you can answer follow-up questions with confidence.", "遇到『克服困难的经历』这类问题，STAR结构很有帮助：\n· 情境(S)：当时是什么情况\n· 任务(T)：你负责什么\n· 行动(A)：具体做了什么\n· 结果(R)：结果如何、学到了什么\n关键是把『行动』讲得最长、最具体。提前用这个框架整理好2~3个经历，就能灵活用于各种问题。因为是真实发生过的事，面对追问也能自信作答。", "Với câu hỏi như 'Kể về lần bạn vượt qua khó khăn', cấu trúc STAR rất hữu ích:\n· Tình huống (S): lúc đó thế nào\n· Nhiệm vụ (T): vai trò của bạn là gì\n· Hành động (A): cụ thể bạn đã làm gì\n· Kết quả (R): ra sao và bạn học được gì\nĐiểm mấu chốt là nói phần 'hành động' dài và cụ thể nhất. Chuẩn bị trước 2–3 kinh nghiệm theo khung này, bạn có thể dùng lại cho nhiều câu hỏi. Vì là chuyện có thật nên bạn có thể tự tin trả lời cả câu hỏi nối tiếp.", "『困難を乗り越えた経験』のような質問にはSTAR構造が役立ちます。\n・状況(S):どんな状況だったか\n・課題(T):自分の役割は何だったか\n・行動(A):具体的に何をしたか\n・結果(R):どうなり、何を学んだか\n特に『行動』を一番長く具体的に話すのがポイントです。経験を2〜3つこの型で整理しておけば、いろいろな質問に使い回せます。実際にあったことなので、深掘りの質問にも自信を持って答えられます。", "Untuk pertanyaan seperti 'Ceritakan tantangan yang pernah Anda atasi', struktur STAR sangat membantu:\n· Situasi (S): apa yang terjadi\n· Tugas (T): apa peran Anda\n· Aksi (A): apa tepatnya yang Anda lakukan\n· Hasil (R): bagaimana hasilnya dan apa pelajarannya\nKuncinya, jadikan bagian 'Aksi' paling panjang dan spesifik. Siapkan 2–3 pengalaman dengan format ini agar bisa dipakai ulang untuk banyak pertanyaan. Karena benar-benar terjadi, Anda bisa menjawab pertanyaan lanjutan dengan percaya diri.") },
        { heading: t("모르면 솔직하게", "Be honest when unsure", "不懂就坦诚", "Không biết thì thành thật", "分からなければ正直に", "Jujur bila tak tahu"), text: t("모르는 건 인정하되 '이렇게 배우겠다'를 덧붙이면 태도로 점수를 얻어요. 질문이 잘 이해되지 않으면 '혹시 ~라는 뜻일까요?'라고 다시 확인해도 괜찮아요. 긴장해서 말이 막히면 잠깐 숨을 고르고 '생각을 정리해서 말씀드려도 될까요?'라고 하면 돼요. 당황하지 않고 대처하는 모습 자체가 좋은 인상을 남겨요. 연습할 때 일부러 어려운 질문을 섞어 대처하는 연습을 해두면 좋아요.", "Admit what you don't know, but add 'here's how I'd learn it' to score on attitude. If you don't quite understand a question, it's fine to check: 'Do you mean ...?' If nerves make you freeze, take a breath and say, 'May I take a moment to organize my thoughts?' Handling it calmly leaves a good impression in itself. When practicing, it helps to mix in tough questions on purpose and rehearse how you'd respond.", "承认不懂，但补上『我会这样去学』，能在态度上得分。没听懂问题时，可以再确认一下：『请问您的意思是……吗？』紧张得说不出话时，先缓口气，说『可以让我整理一下思路再回答吗？』就好。不慌不忙地应对，本身就会留下好印象。练习时故意加入一些难题，练练怎么应对，会很有帮助。", "Thừa nhận điều chưa biết, nhưng thêm 'tôi sẽ học thế này' để ghi điểm thái độ. Nếu chưa hiểu rõ câu hỏi, bạn có thể hỏi lại 'Có phải ý anh/chị là…?'. Nếu căng thẳng đến mức nghẹn lời, hãy hít một hơi và nói 'Tôi xin phép sắp xếp suy nghĩ một chút được không ạ?'. Cách xử lý bình tĩnh tự nó đã để lại ấn tượng tốt. Khi luyện tập, hãy cố ý xen vào vài câu hỏi khó để tập cách xử lý.", "分からないことは認めつつ『こう学びます』を添えると態度で点を得ます。質問がよく分からなければ『〜という意味でしょうか?』と確認しても大丈夫です。緊張して言葉に詰まったら、少し息を整えて『考えをまとめてからお話ししてもよろしいでしょうか』と言えばOKです。慌てずに対処する姿そのものが良い印象を残します。練習のときにわざと難しい質問を混ぜて、対処の練習をしておくと良いです。", "Akui yang tak Anda ketahui, tapi tambahkan 'begini cara saya mempelajarinya' untuk nilai sikap. Jika kurang paham pertanyaannya, tidak apa-apa memastikan: 'Maksud Bapak/Ibu apakah ...?'. Jika gugup sampai kehabisan kata, tarik napas sejenak dan katakan, 'Boleh saya rapikan pikiran sebentar sebelum menjawab?'. Menghadapinya dengan tenang sudah meninggalkan kesan baik. Saat berlatih, sengaja selipkan pertanyaan sulit untuk melatih cara menanggapinya.") },
        { heading: t("유학생이라면", "For international students", "如果你是留学生", "Nếu bạn là du học sinh", "留学生なら", "Untuk mahasiswa asing"), text: t("한국어 면접이 걱정된다면 완벽한 문장보다 또박또박 천천히 말하는 데 집중하세요. 자주 나오는 질문의 답은 한국어로 소리 내어 여러 번 연습하고, 직무 관련 핵심 단어는 정확히 말할 수 있게 준비하면 좋아요. 비자나 체류 기간에 대해 물어볼 수도 있으니, 내 상황을 짧고 명확하게 설명할 수 있도록 미리 정리해두세요. 모의 면접으로 한국어 답변을 미리 연습해보면 실제 자리에서 훨씬 편해져요.", "If you're worried about interviewing in Korean, focus on speaking slowly and clearly rather than in perfect sentences. Practice your answers to common questions out loud in Korean several times, and make sure you can say key job-related words accurately. You may be asked about your visa or length of stay, so prepare to explain your situation briefly and clearly. Practicing your Korean answers in a mock interview makes the real thing much more comfortable.", "如果担心韩语面试，与其追求完美的句子，不如专注于一字一句、慢慢说清楚。常见问题的答案用韩语出声练习多遍，确保能准确说出与职位相关的关键词。面试中可能会问到签证或居留期限，提前整理好，能简短清楚地说明自己的情况。通过模拟面试提前练习韩语回答，真正面试时会轻松很多。", "Nếu lo lắng về phỏng vấn bằng tiếng Hàn, hãy tập trung nói chậm và rõ ràng thay vì câu hoàn hảo. Luyện nói to câu trả lời cho các câu hỏi thường gặp bằng tiếng Hàn nhiều lần, và chuẩn bị để nói chính xác các từ khóa liên quan đến công việc. Có thể bạn sẽ được hỏi về visa hoặc thời gian lưu trú, nên hãy chuẩn bị trước để giải thích tình hình của mình ngắn gọn, rõ ràng. Luyện trước câu trả lời tiếng Hàn qua phỏng vấn mô phỏng sẽ giúp bạn thoải mái hơn nhiều khi phỏng vấn thật.", "韓国語の面接が心配なら、完璧な文より、はっきりゆっくり話すことに集中しましょう。よく出る質問の答えは韓国語で何度も声に出して練習し、職務関連のキーワードは正確に言えるよう準備すると良いです。ビザや滞在期間について聞かれることもあるので、自分の状況を短く明確に説明できるよう整理しておきましょう。模擬面接で韓国語の回答を事前に練習しておくと、本番でずっと楽になります。", "Jika khawatir wawancara dalam bahasa Korea, fokuslah berbicara pelan dan jelas, bukan kalimat yang sempurna. Latih jawaban pertanyaan umum dengan suara keras dalam bahasa Korea berkali-kali, dan pastikan Anda bisa mengucapkan kata kunci terkait pekerjaan dengan tepat. Anda mungkin ditanya soal visa atau masa tinggal, jadi siapkan penjelasan singkat dan jelas tentang situasi Anda. Berlatih jawaban bahasa Korea lewat simulasi wawancara membuat wawancara sungguhan jauh lebih nyaman.") },
        { heading: t("면접 전날 체크리스트", "Night-before checklist", "面试前一天清单", "Danh sách đêm trước", "面接前日のチェック", "Daftar cek malam sebelumnya"), text: t("면접 전날 이것만 확인해요.\n· 단골 질문 3개 답변 소리 내어 연습하기\n· 공고와 회사 서비스 한 번 더 살펴보기\n· 회사에 물어볼 질문 1~2개 준비하기\n· 장소·시간·접속 링크와 복장 확인하기\n마지막으로 모의 면접을 한 번 해보면 실제 면접에서 훨씬 덜 긴장돼요. 충분히 쉬고 컨디션을 챙기는 것도 준비의 일부예요. 면접 당일에는 조금 일찍 도착하거나 접속해 마음을 가라앉히세요.", "The night before, just check these:\n· Practice the 3 regular answers out loud\n· Review the posting and the company's service once more\n· Prepare 1–2 questions to ask the company\n· Confirm the location, time, meeting link, and outfit\nFinally, doing one mock interview makes the real one far less nerve-racking. Getting enough rest and taking care of your condition is part of preparing too. On the day, arrive or log in a little early to settle your nerves.", "面试前一天，只要确认这些：\n· 出声练习3个常见问题的回答\n· 再看一遍招聘信息和公司的服务\n· 准备1~2个要问公司的问题\n· 确认地点、时间、线上链接和着装\n最后做一次模拟面试，真正面试时就不会那么紧张了。好好休息、调整状态，也是准备的一部分。面试当天提早一点到场或上线，让自己平静下来。", "Đêm trước buổi phỏng vấn, chỉ cần kiểm tra:\n· Luyện nói to câu trả lời cho 3 câu hỏi quen thuộc\n· Xem lại tin tuyển dụng và dịch vụ của công ty\n· Chuẩn bị 1–2 câu hỏi để hỏi công ty\n· Kiểm tra địa điểm, giờ, link họp và trang phục\nCuối cùng, thử một buổi phỏng vấn mô phỏng sẽ giúp bạn bớt run hơn nhiều khi phỏng vấn thật. Nghỉ ngơi đủ và giữ sức khỏe cũng là một phần của việc chuẩn bị. Vào ngày phỏng vấn, hãy đến hoặc vào phòng họp trực tuyến sớm một chút để bình tĩnh lại.", "面接の前日はこれだけ確認しましょう。\n・定番質問3つの答えを声に出して練習\n・求人と会社のサービスをもう一度確認\n・会社に聞きたい質問を1〜2個準備\n・場所・時間・接続リンクと服装を確認\n最後に模擬面接を一度やってみると、本番でずっと緊張しにくくなります。十分に休んで体調を整えることも準備の一部です。面接当日は少し早めに到着またはログインして、気持ちを落ち着けましょう。", "Malam sebelum wawancara, cukup cek ini:\n· Latih jawaban 3 pertanyaan langganan dengan suara keras\n· Tinjau lagi lowongan dan layanan perusahaan\n· Siapkan 1–2 pertanyaan untuk perusahaan\n· Pastikan lokasi, waktu, tautan rapat, dan pakaian\nTerakhir, mencoba satu kali simulasi wawancara membuat wawancara sungguhan jauh lebih tidak menegangkan. Istirahat cukup dan menjaga kondisi juga bagian dari persiapan. Pada hari wawancara, datang atau masuk sedikit lebih awal untuk menenangkan diri.") }
      ]
    }
  ];
}
